/// Section 8 of the part-3e design: fixture Q. The phase-2 cases run last:
/// they follow the deletion of two resource rows.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_predicate_compiler_computes_with_set_operands() {
    skip_unless_live!();
    let db = pulsus_testkit::test_db("pulsus_read_it_t589p3e_fixtureq");
    let client = fresh_db(&db).await;
    let base_ns = (now_ns() / 1_000_000_000) * 1_000_000_000;
    for (i, req) in fixture_q_bodies(base_ns).into_iter().enumerate() {
        land(&client, &req, &format!("t589p3e-q-{i}-{}", now_ns())).await;
    }
    let w = WindowSql::start_closed_end_open(base_ns, base_ns + WINDOW_NS);

    let seeded = count(&client, &format!("SELECT count() AS n FROM {SPANS_TABLE}")).await;
    assert_eq!(
        seeded, 22,
        "fixture Q seeds twenty-two spans; nothing below can be read as a predicate result \
         until this holds"
    );
    let ids = ids_of(
        &client,
        &format!("SELECT lower(hex(span_id)) AS id FROM {SPANS_TABLE} ORDER BY id"),
    )
    .await;
    let want: Vec<String> = ALL_Q.iter().copied().map(idq).collect();
    assert_eq!(ids, want, "the 22 span ids are fixture Q's");

    let mut wrong = run_cases_in(&client, w, CASES_Q, idq).await;
    for span in ["q18", "q21"] {
        delete_resource_row_of(&client, &idq(span)).await;
    }
    wrong.extend(run_cases_in(&client, w, CASES_Q_MISS, idq).await);
    drop_db(&db).await;
    assert!(
        wrong.is_empty(),
        "{} of {} fixture-Q cases answer something else:\n\n{}",
        wrong.len(),
        CASES_Q.len() + CASES_Q_MISS.len(),
        wrong.join("\n\n")
    );
}

// =====================================================================
// Issue #590 — the search statement
// =====================================================================

/// Runs [`search_sql`] for `query` over the window and decodes its rows.
async fn search_rows(
    client: &ChClient,
    w: WindowSql,
    query: &str,
    limit: u32,
    spss: u32,
    settings: QuerySettings,
) -> Vec<SearchTraceRow> {
    let parsed =
        pulsus_traceql::parse(query).unwrap_or_else(|e| panic!("{query} must parse: {e:?}"));
    let body = match parsed.spanset {
        SpansetExpr::Filter(SpansetFilter { body: Some(b) }) => b,
        SpansetExpr::Filter(SpansetFilter { body: None }) => FieldExpr::Literal(Value::Bool(true)),
        other => panic!("{query}: expected one filter, got {other}"),
    };
    let p = compile_span_predicate_in(&body, &ctx_of(w))
        .unwrap_or_else(|e| panic!("{query} must compile: {e}"));
    let sql = search_sql(
        SPANS_TABLE,
        "traces",
        w,
        &SearchFilter::One(p),
        &Projection::none(),
        limit,
        spss,
    );
    let mut stream = client
        .query_stream::<SearchTraceRow>(&sql.replace('?', "??"), &settings)
        .await
        .unwrap_or_else(|e| panic!("the search failed: {e}\nSQL:\n{sql}"));
    let mut out = Vec::new();
    while let Some(row) = stream.next().await {
        out.push(row.unwrap_or_else(|e| panic!("decode failed: {e}\nSQL:\n{sql}")));
    }
    out
}

/// One returned trace as `(trace id hex, matched, span id hexes)`.
fn search_summary(rows: &[SearchTraceRow]) -> Vec<(String, u64, Vec<String>)> {
    let hex = |b: &[u8]| b.iter().map(|x| format!("{x:02x}")).collect::<String>();
    rows.iter()
        .map(|r| {
            (
                hex(&r.trace_id),
                r.matched,
                r.spans.iter().map(|s| hex(&s.span_id)).collect(),
            )
        })
        .collect()
}

fn trace_hex(byte: u8) -> String {
    format!("{byte:02x}").repeat(16)
}

/// `F1` (§6.1, `{}`), with `spss = 9` and `spss = 3`.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn f1_the_search_statement_returns_every_trace_newest_first() {
    skip_unless_live!();
    let db = pulsus_testkit::test_db("pulsus_read_it_t590_fixture61");
    let client = fresh_db(&db).await;
    let base_ns = (now_ns() / 1_000_000_000) * 1_000_000_000;
    for (i, req) in fixture_61_bodies(base_ns).into_iter().enumerate() {
        land(&client, &req, &format!("t590-61-{i}-{}", now_ns())).await;
    }
    let w = WindowSql::start_closed_end_open(base_ns, base_ns + WINDOW_NS);
    let seeded = count(&client, &format!("SELECT count() AS n FROM {SPANS_TABLE}")).await;
    assert_eq!(seeded, 9, "the §6.1 fixture seeds nine spans");

    let all = search_summary(&search_rows(&client, w, "{}", 20, 9, read_settings()).await);
    let capped = search_summary(&search_rows(&client, w, "{}", 20, 3, read_settings()).await);
    drop_db(&db).await;
    let ids = |v: &[&str]| v.iter().map(|s| id61(s)).collect::<Vec<_>>();
    assert_eq!(
        all,
        vec![
            (trace_hex(0x33), 2, ids(&["0008", "0009"])),
            (trace_hex(0x22), 1, ids(&["0007"])),
            (
                trace_hex(0x11),
                6,
                ids(&["0001", "0002", "0003", "0004", "0005", "0006"])
            ),
        ],
        "F1, spss = 9"
    );
    assert_eq!(
        capped,
        vec![
            (trace_hex(0x33), 2, ids(&["0008", "0009"])),
            (trace_hex(0x22), 1, ids(&["0007"])),
            (trace_hex(0x11), 6, ids(&["0001", "0002", "0003"])),
        ],
        "F1, spss = 3"
    );
}

/// Fixture K: trace `c1…c1` with spans `…11` to `…15` at `base + 1…5 ms`,
/// and traces `a2…a2` (span `…21`) and `a3…a3` (span `…31`), each one span
/// at `base + 9 ms`. One request per span, service `k`.
fn fixture_k_bodies(base_ns: i64) -> Vec<ExportTraceServiceRequest> {
    const MS: i64 = 1_000_000;
    let spans: Vec<(u8, u8, i64)> = vec![
        (0xc1, 0x11, 1),
        (0xc1, 0x12, 2),
        (0xc1, 0x13, 3),
        (0xc1, 0x14, 4),
        (0xc1, 0x15, 5),
        (0xa2, 0x21, 9),
        (0xa3, 0x31, 9),
    ];
    spans
        .into_iter()
        .map(|(trace, span, at_ms)| {
            one_span_request(
                vec![kv("service.name", str_value("k"))],
                scope_named("io.pulsus.k", "1.0", Vec::new()),
                span_of(
                    vec![trace; 16],
                    vec![0, 0, 0, 0, 0, 0, 0, span],
                    Vec::new(),
                    "op",
                    1,
                    base_ns + at_ms * MS,
                    MS,
                    Vec::new(),
                    0,
                    Vec::new(),
                    Vec::new(),
                ),
            )
        })
        .collect()
}

/// Seeds fixture K in `db`, a name `pulsus_testkit::test_db` composed.
async fn seed_fixture_k(db: String) -> (String, ChClient, WindowSql) {
    let client = fresh_db(&db).await;
    let base_ns = (now_ns() / 1_000_000_000) * 1_000_000_000;
    for (i, req) in fixture_k_bodies(base_ns).into_iter().enumerate() {
        land(&client, &req, &format!("t590-k-{i}-{}", now_ns())).await;
    }
    let seeded = count(&client, &format!("SELECT count() AS n FROM {SPANS_TABLE}")).await;
    assert_eq!(seeded, 7, "fixture K seeds seven spans");
    let w = WindowSql::start_closed_end_open(base_ns, base_ns + WINDOW_NS);
    (db, client, w)
}

/// The functional requirements' `T-C3`: `matched` counts before the cap.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn fr_t_c3_matched_counts_before_the_cap() {
    skip_unless_live!();
    let (db, client, w) =
        seed_fixture_k(pulsus_testkit::test_db("pulsus_read_it_t590_fixturek_c3")).await;
    let rows = search_summary(&search_rows(&client, w, "{}", 20, 3, read_settings()).await);
    drop_db(&db).await;
    let c1 = rows
        .iter()
        .find(|(t, _, _)| *t == trace_hex(0xc1))
        .unwrap_or_else(|| panic!("trace c1 is returned: {rows:?}"));
    let span = |b: u8| format!("{:016x}", b);
    assert_eq!(
        (c1.1, c1.2.clone()),
        (5, vec![span(0x11), span(0x12), span(0x13)]),
        "matched is the uncapped count and the spanset the first three"
    );
}

/// The functional requirements' `T-C4`: a tie on the newest matched span
/// orders by trace id ascending.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn fr_t_c4_a_tie_orders_by_trace_id() {
    skip_unless_live!();
    let (db, client, w) =
        seed_fixture_k(pulsus_testkit::test_db("pulsus_read_it_t590_fixturek_c4")).await;
    let rows = search_summary(&search_rows(&client, w, "{}", 20, 3, read_settings()).await);
    drop_db(&db).await;
    let order: Vec<String> = rows.into_iter().map(|(t, _, _)| t).collect();
    assert_eq!(
        order,
        vec![trace_hex(0xa2), trace_hex(0xa3), trace_hex(0xc1)]
    );
}

/// Corpus S's three hours, ending at the test's own whole second.
const CORPUS_S_NS: i64 = 10_800_000_000_000;

/// The per-trace table, from the spans, by `traces_mv`'s own `SELECT`.
const TRACES_FROM_SPANS: &str = "INSERT INTO traces SELECT toDate(fromUnixTimestamp64Nano(s), 'UTC') AS day, trace_id, \
     s AS start_ns, e AS end_ns, r AS root, sv AS services, \
     ls AS last_start_ns, bk AS buckets \
     FROM (SELECT trace_id, min(start_ns) AS s, \
     max(toInt64(least(toUInt64(start_ns) + toUInt64(duration_ns), 9223372036854775807))) AS e, \
     min((toUInt8(parent_span_id != toFixedString('', 8)), start_ns, span_id, \
     toString(service), toString(name))) AS r, \
     groupUniqArray(toString(service)) AS sv, max(start_ns) AS ls, \
     groupUniqArray(4096)(intDiv(start_ns, 300000000000)) AS bk \
     FROM spans GROUP BY trace_id)";

/// One corpus-S statement, its threads and memory bounded: the server is
/// shared.
async fn run_bounded(client: &ChClient, sql: String) {
    let bounded = QuerySettings::new()
        .set("max_threads", 4)
        .set("max_memory_usage", 4_000_000_000_u64);
    client
        .execute(&sql, &bounded, Idempotency::Idempotent)
        .await
        .unwrap_or_else(|e| panic!("corpus S: {e}\nSQL:\n{sql}"));
}

/// Seeds corpus S: 70,000 traces of 28 spans over three hours — the sixth
/// span of each an error (issue #591 part 3's `T-Q2`) — then the
/// per-trace table by `traces_mv`'s own `SELECT` over the spans, then the
/// span table merged, in `db`, a name `pulsus_testkit::test_db` composed.
/// Returns the database, its client and the window.
async fn seed_corpus_s(db: String) -> (String, ChClient, WindowSql) {
    let client = fresh_db(&db).await;
    let base_ns = (now_ns() / 1_000_000_000) * 1_000_000_000 - CORPUS_S_NS;
    run_bounded(
        &client,
        format!(
            "INSERT INTO {SPANS_TABLE} (trace_id, span_id, parent_span_id, start_ns, duration_ns, \
         service, name, kind, end_ns, service_type, status_code) \
         SELECT sipHash128(t), reinterpretAsFixedString(cityHash64(t, i)), \
         if(i = 0, toFixedString('', 8), reinterpretAsFixedString(cityHash64(t, 0))), \
         {base_ns} + intDiv(t * {CORPUS_S_NS}, 70000) + i * 1000000, 1000000, \
         ['frontend', 'checkout', 'cart', 'payment'][1 + (t + i) % 4], 'op', 1, \
         toUInt64({base_ns} + intDiv(t * {CORPUS_S_NS}, 70000) + i * 1000000 + 1000000), \
         'string', if(i = 5, 2, 0) \
         FROM (SELECT number AS t, arrayJoin(range(28)) AS i FROM numbers(70000))"
        ),
    )
    .await;
    run_bounded(&client, TRACES_FROM_SPANS.to_string()).await;
    run_bounded(&client, format!("OPTIMIZE TABLE {SPANS_TABLE} FINAL")).await;
    let seeded = count(&client, &format!("SELECT count() AS n FROM {SPANS_TABLE}")).await;
    assert_eq!(seeded, 1_960_000, "corpus S seeds 1,960,000 spans");
    let w = WindowSql::start_closed_end_open(base_ns, base_ns + CORPUS_S_NS);
    (db, client, w)
}

/// `W`: the spans the window's three clauses select.
async fn window_spans(client: &ChClient, w: WindowSql) -> u64 {
    count(
        client,
        &format!(
            "SELECT count() AS n FROM {SPANS_TABLE} WHERE {} AND {} AND {}",
            w.span_time_clause(),
            w.span_bucket_clause(),
            w.span_day_clause()
        ),
    )
    .await
}

/// Runs the search for `{}` with `limit = 20`, `spss = 3`, tagged so its
/// `system.query_log` row can be found by `comment`, a name
/// `pulsus_testkit::test_ident` composed; returns its rows and its
/// `read_rows`.
async fn logged_search(
    client: &ChClient,
    w: WindowSql,
    comment: String,
) -> (Vec<SearchTraceRow>, u64) {
    let settings = read_settings()
        .set("max_threads", 4)
        .set("max_memory_usage", 4_000_000_000_u64)
        .set("log_comment", &comment);
    let rows = search_rows(client, w, "{}", 20, 3, settings).await;
    client
        .execute(
            "SYSTEM FLUSH LOGS",
            &QuerySettings::new(),
            Idempotency::Idempotent,
        )
        .await
        .expect("flush the logs");
    let read_rows = count(
        client,
        &format!(
            "SELECT read_rows AS n FROM system.query_log WHERE log_comment = '{comment}' \
             AND type = 'QueryFinish' AND current_database = currentDatabase() \
             ORDER BY event_time_microseconds DESC LIMIT 1"
        ),
    )
    .await;
    (rows, read_rows)
}

/// `the top-K runs once`: the statement reads the window about once — the
/// top-K is a scalar, computed once, not an inlined expression read by
/// both later reads.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_top_k_runs_once() {
    skip_unless_live!();
    let (db, client, w) =
        seed_corpus_s(pulsus_testkit::test_db("pulsus_read_it_t590_corpus_s_topk")).await;
    let window = window_spans(&client, w).await;
    let (rows, read_rows) =
        logged_search(&client, w, pulsus_testkit::test_ident("t590_topk")).await;
    drop_db(&db).await;
    assert_eq!(rows.len(), 20, "twenty traces");
    assert!(
        read_rows as f64 <= 1.05 * window as f64,
        "the statement read {read_rows} rows against a window of {window}: more than 1.05 times"
    );
}

/// `the detail read does not re-scan the window`: what the statement
/// reads beyond the window is within the plan's granule bound for the
/// keyed detail read and the per-trace read, and less than the window.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_detail_read_does_not_re_scan_the_window() {
    skip_unless_live!();
    let (db, client, w) = seed_corpus_s(pulsus_testkit::test_db(
        "pulsus_read_it_t590_corpus_s_detail",
    ))
    .await;
    let window = window_spans(&client, w).await;
    let (rows, read_rows) =
        logged_search(&client, w, pulsus_testkit::test_ident("t590_detail")).await;
    let clauses = format!(
        "{} AND {} AND {}",
        w.span_time_clause(),
        w.span_bucket_clause(),
        w.span_day_clause()
    );
    // `K`: the (bucket, trace) keys of the top twenty; `S`: the spans in
    // them.
    let top = format!(
        "SELECT trace_id, max(start_ns) AS last, \
         groupUniqArray(intDiv(start_ns, 300000000000)) AS keys \
         FROM {SPANS_TABLE} WHERE {clauses} GROUP BY trace_id \
         ORDER BY last DESC, trace_id ASC LIMIT 20"
    );
    let keys = count(
        &client,
        &format!("SELECT sum(length(keys)) AS n FROM ({top})"),
    )
    .await;
    let spans = count(
        &client,
        &format!(
            "SELECT count() AS n FROM {SPANS_TABLE} WHERE {clauses} \
             AND trace_id IN (SELECT trace_id FROM ({top}))"
        ),
    )
    .await;
    let parts = count(
        &client,
        "SELECT count() AS n FROM system.parts WHERE database = currentDatabase() \
         AND table = 'traces' AND active",
    )
    .await;
    drop_db(&db).await;
    let limit = rows.len() as u64;
    assert_eq!(limit, 20, "twenty traces");
    let bound = 2_048 * (2 * keys + spans.div_ceil(2_048)) + 1_024 * limit * parts + 2;
    let beyond = read_rows.saturating_sub(window);
    assert!(
        read_rows >= window && beyond <= bound,
        "the statement read {read_rows} rows over a window of {window}: {beyond} beyond it, \
         against the bound 2048 x (2 x {keys} + ceil({spans} / 2048)) + 1024 x {limit} x {parts} \
         + 2 = {bound}"
    );
    assert!(
        beyond < window,
        "{beyond} beyond the window is not less than it ({window})"
    );
}

// =====================================================================
// Issue #591 part 1 — the search statement against today's engine
// =====================================================================

/// Today's engine's configuration: the old tables, as
/// `traces_search_projection_differential.rs` configures it.
fn engine_config() -> pulsus_read::TraceReadConfig {
    pulsus_read::TraceReadConfig {
        read_max_memory_bytes: 8 * 1024 * 1024 * 1024,
        spans_table: "trace_spans".to_string(),
        attrs_table: "trace_attrs_idx".to_string(),
        edges_table: "trace_edges".to_string(),
        recent_table: "trace_recent".to_string(),
        errors_table: "trace_error_spans".to_string(),
        spans_v2_table: "spans".to_string(),
        traces_table: "traces".to_string(),
        resources_table: "resources".to_string(),
        max_candidates: 100_000,
        scan_budget_rows: 50_000_000,
        event_set_max_values: 1_000_000,
        max_depth: 64,
        max_series: 1_000,
        generator_max_memory_bytes: 536_870_912,
        distributed: false,
        skip_unavailable_shards: false,
    }
}

fn client_config(db: &str) -> ChConnConfig {
    ChConnConfig {
        database: db.to_string(),
        ..base_config()
    }
}

/// Lands each request in BOTH stores: the old tables through today's trace
/// writer, and the new ones through `trace_landing`, as [`land`] does —
/// the same request, so the two engines read the same pushes.
async fn land_both(client: &ChClient, db: &str, reqs: &[ExportTraceServiceRequest], tag: &str) {
    use pulsus_write::writer::{ChBlockInserter, TraceWriter, TraceWriterTables};
    use pulsus_write::{ParsedTraceLanding, PushHeaders, TraceSink};
    use std::sync::Arc;
    let writer_client = Arc::new(
        ChClient::new(client_config(db))
            .await
            .expect("connect the writer"),
    );
    let mut cfg = pulsus_config::WriterConfig::default();
    cfg.batch_bytes.0 = 1;
    let writer = TraceWriter::with_inserters_with_tables(
        Arc::new(ChBlockInserter::new(writer_client.clone())),
        Arc::new(ChBlockInserter::new(writer_client.clone())),
        Arc::new(ChBlockInserter::new(writer_client.clone())),
        &cfg,
        TraceWriterTables::traces_default(),
    );
    for (i, req) in reqs.iter().enumerate() {
        let parsed = pulsus_write::parse_traces(req, now_ns()).expect("the old path parses");
        let wait = writer
            .admit_flush(
                parsed,
                ParsedTraceLanding::default(),
                PushHeaders::default(),
            )
            .expect("the queue has room");
        tokio::time::timeout(StdDuration::from_secs(30), wait)
            .await
            .expect("the old path's flush settles")
            .expect("the old path commits");
        land(client, req, &format!("{tag}-{i}-{}", now_ns())).await;
    }
}

/// Today's answer to `query` over the window.
async fn today(
    db: &str,
    query: &pulsus_traceql::Query,
    w: (i64, i64),
    limit: u32,
    spss: u32,
) -> Result<pulsus_read::traces::SearchOutput, String> {
    use pulsus_read::traces::search_plan::{SearchParams, plan_search};
    let engine = pulsus_read::TraceEngine::new(
        ChClient::new(client_config(db))
            .await
            .expect("connect the engine"),
        engine_config(),
    );
    let plan = plan_search(
        query,
        &SearchParams {
            start_ns: w.0,
            end_ns: w.1,
            limit,
            spss,
        },
        &engine.search_ctx(),
    )
    .map_err(|e| format!("today's planner refused: {e}"))?;
    engine
        .search(&plan)
        .await
        .map_err(|e| format!("today's engine failed: {e}"))
}

/// The search statement's answer to `query` over the window, decoded.
async fn statement(
    client: &ChClient,
    query: &pulsus_traceql::Query,
    w: (i64, i64),
    limit: u32,
    spss: u32,
) -> Result<pulsus_read::traces::SearchOutput, String> {
    let window = WindowSql::start_closed_end_open(w.0, w.1);
    let stmt = compile_search(query, &ctx_of(window), SPANS_TABLE, "traces", limit, spss)
        .map_err(|e| format!("the statement refused: {e}"))?;
    let mut stream = client
        .query_stream::<SearchTraceRow>(&stmt.sql().replace('?', "??"), &read_settings())
        .await
        .map_err(|e| format!("the statement failed: {e}"))?;
    let mut rows = Vec::new();
    while let Some(row) = stream.next().await {
        rows.push(row.map_err(|e| format!("decode failed: {e}"))?);
    }
    decode_search(rows, stmt.projection(), limit).map_err(|e| format!("{e:?}"))
}

fn parse_query(query: &str) -> pulsus_traceql::Query {
    pulsus_traceql::parse(query).unwrap_or_else(|e| panic!("{query} must parse: {e:?}"))
}

/// The normalisation of today's side (section 8.3): the root span's own
/// start and duration are `0` on the new side (decision 5), and trace
/// `5555…`'s root is empty there (decision 4).
fn normalise_today(
    mut out: pulsus_read::traces::SearchOutput,
) -> pulsus_read::traces::SearchOutput {
    for t in &mut out.traces {
        t.root.start_ns = 0;
        t.root.duration_ns = 0;
        if t.trace_id == [0x55; 16] {
            t.root.service.clear();
            t.root.name.clear();
        }
    }
    out
}

/// Fixture RZ (issue #591 part 1's fixture Z), one body: trace `aa…` with
/// two roots and a child, and trace `bb…` whose spans hold arrays and
/// numbers.
fn fixture_rz_body(base_ns: i64) -> ExportTraceServiceRequest {
    const MS: i64 = 1_000_000;
    let arr = |values: Vec<AnyValue>| AnyValue {
        value: Some(any_value::Value::ArrayValue(ArrayValue { values })),
    };
    let sp = |trace: u8, span: u8, parent: u8, name: &str, at_ms: i64, attrs: Vec<KeyValue>| {
        span_of(
            vec![trace; 16],
            vec![0, 0, 0, 0, 0, 0, 0, span],
            if parent == 0 {
                Vec::new()
            } else {
                vec![0, 0, 0, 0, 0, 0, 0, parent]
            },
            name,
            1,
            base_ns + at_ms * MS,
            MS,
            attrs,
            0,
            Vec::new(),
            Vec::new(),
        )
    };
    let rs = |service: &str, spans: Vec<Span>| ResourceSpans {
        resource: Some(Resource {
            attributes: vec![kv("service.name", str_value(service))],
            dropped_attributes_count: 0,
            entity_refs: Vec::new(),
        }),
        scope_spans: vec![ScopeSpans {
            scope: Some(scope_named("io.pulsus.rz", "1.0", Vec::new())),
            spans,
            schema_url: String::new(),
        }],
        schema_url: String::new(),
    };
    ExportTraceServiceRequest {
        resource_spans: vec![
            rs("svc-a", vec![sp(0xaa, 0xa1, 0, "z-name", 0, Vec::new())]),
            rs(
                "svc-z",
                vec![
                    sp(0xaa, 0xa2, 0, "a-name", 1, Vec::new()),
                    sp(0xaa, 0xa3, 0xa1, "child", 2, Vec::new()),
                ],
            ),
            rs(
                "svc-b",
                vec![
                    sp(
                        0xbb,
                        0xb1,
                        0,
                        "arrays",
                        10,
                        vec![
                            kv("tags", str_array_value(&["gold", "eu"])),
                            kv("ints", int_array_value(&[1, 2])),
                            kv("floats", arr(vec![double_value(1.5), double_value(2.0)])),
                            kv("bools", arr(vec![bool_value(true), bool_value(false)])),
                            kv("mixed", arr(vec![str_value("a"), int_value(1)])),
                            kv("a", int_value(3)),
                        ],
                    ),
                    sp(
                        0xbb,
                        0xb2,
                        0xb1,
                        "eight",
                        11,
                        vec![kv("a", int_value(8)), kv("f", double_value(2.0))],
                    ),
                    sp(
                        0xbb,
                        0xb3,
                        0xb1,
                        "ratio",
                        12,
                        vec![kv("a", double_value(2.5))],
                    ),
                ],
            ),
        ],
    }
}

/// Fixture B: one root span per trace `f1…` to `f8…`, each holding one
/// value at or just past the 8,192-byte response ceiling.
fn fixture_b_bodies(base_ns: i64) -> Vec<ExportTraceServiceRequest> {
    const MS: i64 = 1_000_000;
    let n = |count: usize| "n".repeat(count);
    let wide = format!("{}nn", "日".repeat(2730));
    let wider = format!("{}nnn", "日".repeat(2730));
    // (trace byte, service, root name, span attributes)
    let rows: Vec<(u8, String, String, Vec<KeyValue>)> = vec![
        (0xf1, "b".to_string(), n(8192), Vec::new()),
        (0xf2, "b".to_string(), n(8193), Vec::new()),
        (0xf3, wide, "op".to_string(), Vec::new()),
        (0xf4, wider, "op".to_string(), Vec::new()),
        (
            0xf5,
            "b".to_string(),
            "op".to_string(),
            vec![kv("s", str_value(&n(8192)))],
        ),
        (
            0xf6,
            "b".to_string(),
            "op".to_string(),
            vec![kv("s", str_value(&n(8193)))],
        ),
        (
            0xf7,
            "b".to_string(),
            "op".to_string(),
            vec![kv("arr", str_array_value(&[&n(8188)]))],
        ),
        (
            0xf8,
            "b".to_string(),
            "op".to_string(),
            vec![kv("arr", str_array_value(&[&n(8189)]))],
        ),
    ];
    rows.into_iter()
        .enumerate()
        .map(|(i, (trace, service, name, attrs))| {
            one_span_request(
                vec![kv("service.name", str_value(&service))],
                scope_named("io.pulsus.b", "1.0", Vec::new()),
                span_of(
                    vec![trace; 16],
                    vec![0, 0, 0, 0, 0, 0, 0, trace],
                    Vec::new(),
                    &name,
                    1,
                    base_ns + (i as i64 + 1) * MS,
                    MS,
                    attrs,
                    0,
                    Vec::new(),
                    Vec::new(),
                ),
            )
        })
        .collect()
}

/// Fixture P (issue #591 part 2's section 7.2), one body: trace `11…` with
/// a root holding events, links and a scope, and a child; trace `22…` with
/// one root. Event times are offsets from `base_ns`, so `…02`'s and
/// `…03`'s events sit at their spans' own start.
fn fixture_p_body(base_ns: i64) -> ExportTraceServiceRequest {
    const MS: i64 = 1_000_000;
    let span_id = |b: u8| vec![0, 0, 0, 0, 0, 0, 0, b];
    let arr = |values: &[&str]| str_array_value(values);
    let resource = |attributes: Vec<KeyValue>| Resource {
        attributes,
        dropped_attributes_count: 0,
        entity_refs: Vec::new(),
    };
    let link = |first: u8, last: u8, attrs: Vec<KeyValue>| {
        link_of(vec![0x99; 16], vec![first, 0, 0, 0, 0, 0, 0, last], attrs)
    };
    let root = span_of(
        vec![0x11; 16],
        span_id(1),
        Vec::new(),
        "p-root",
        2,
        base_ns,
        10 * MS,
        vec![kv("q", str_value("span-q"))],
        0,
        vec![
            event_of(
                base_ns + MS,
                "alpha",
                vec![
                    kv("k", int_value(1)),
                    kv("t", str_value("a")),
                    kv("r", str_value("ev-r1")),
                ],
            ),
            event_of(
                base_ns + 2 * MS,
                "beta",
                vec![kv("k", int_value(5)), kv("r", str_value("ev-r2"))],
            ),
            event_of(
                base_ns + 3 * MS,
                "gamma",
                vec![kv("k", int_value(9)), kv("t", str_value("b"))],
            ),
        ],
        vec![
            link(
                0x0a,
                0x01,
                vec![kv("lk", int_value(2)), kv("s", str_value("link-s1"))],
            ),
            link(
                0x0b,
                0x02,
                vec![kv("lk", int_value(6)), kv("s", str_value("link-s2"))],
            ),
            link(0x0c, 0x03, vec![kv("lk", int_value(10))]),
        ],
    );
    let child = span_of(
        vec![0x11; 16],
        span_id(2),
        span_id(1),
        "p-child",
        1,
        base_ns + 4 * MS,
        MS,
        vec![kv("k", str_value("span-k"))],
        0,
        vec![event_of(
            base_ns + 4 * MS,
            "delta",
            vec![kv("k", int_value(3))],
        )],
        Vec::new(),
    );
    let other = span_of(
        vec![0x22; 16],
        span_id(3),
        Vec::new(),
        "p-other",
        1,
        base_ns + 20 * MS,
        MS,
        vec![kv("k", double_value(2.5))],
        0,
        vec![event_of(
            base_ns + 20 * MS,
            "beta",
            vec![kv("k", double_value(4.5)), kv("t", arr(&["x", "y"]))],
        )],
        Vec::new(),
    );
    ExportTraceServiceRequest {
        resource_spans: vec![
            ResourceSpans {
                resource: Some(resource(vec![
                    kv("service.name", str_value("svc-p")),
                    kv("rk_s", str_value("rv")),
                    kv("rk_i", int_value(7)),
                    kv("rk_d", double_value(2.5)),
                    kv("rk_b", bool_value(true)),
                    kv("rk_arr", arr(&["x", "y"])),
                    kv("p", str_value("res")),
                    kv("q", str_value("res-q")),
                ])),
                scope_spans: vec![ScopeSpans {
                    scope: Some(scope_named(
                        "sc",
                        "1",
                        vec![kv("u", str_value("instr-u")), kv("s", str_value("instr-s"))],
                    )),
                    spans: vec![root],
                    schema_url: String::new(),
                }],
                schema_url: String::new(),
            },
            ResourceSpans {
                resource: Some(resource(vec![
                    kv("service.name", str_value("svc-q")),
                    kv("p", int_value(42)),
                    kv("rk_i", int_value(3)),
                ])),
                scope_spans: vec![ScopeSpans {
                    scope: Some(scope_named("sc2", "2", Vec::new())),
                    spans: vec![child, other],
                    schema_url: String::new(),
                }],
                schema_url: String::new(),
            },
        ],
    }
}

/// Fixture S: one span, `33…`/`…04`, whose events hold `k` = 2 then 5 and
/// whose links hold `lk` = 2 then 5, and nothing else holds `k` or `lk`.
/// The two-element sets on which the elementwise rule of
/// `docs/benchmarks/traces-differential-ledger.md`,
/// `traceql-event-link-set-operands`, answers where today's engine,
/// reading the first element, does not.
fn fixture_s_body(base_ns: i64) -> ExportTraceServiceRequest {
    const MS: i64 = 1_000_000;
    one_span_request(
        vec![kv("service.name", str_value("svc-s"))],
        scope_named("io.pulsus.s", "1.0", Vec::new()),
        span_of(
            vec![0x33; 16],
            vec![0, 0, 0, 0, 0, 0, 0, 4],
            Vec::new(),
            "s-root",
            1,
            base_ns + 30 * MS,
            MS,
            Vec::new(),
            0,
            vec![
                event_of(base_ns + 30 * MS, "e1", vec![kv("k", int_value(2))]),
                event_of(base_ns + 31 * MS, "e2", vec![kv("k", int_value(5))]),
            ],
            vec![
                link_of(
                    vec![0x99; 16],
                    vec![0x0d, 0, 0, 0, 0, 0, 0, 1],
                    vec![kv("lk", int_value(2))],
                ),
                link_of(
                    vec![0x99; 16],
                    vec![0x0d, 0, 0, 0, 0, 0, 0, 2],
                    vec![kv("lk", int_value(5))],
                ),
            ],
        ),
    )
}

