/// The `(limit, spss)` pairs every comparison runs at.
const LIMIT_SPSS: [(u32, u32); 3] = [(100, 100), (20, 3), (2, 1)];

/// Seeds `bodies` in both stores of a fresh database, asserting the two
/// span counts first.
async fn seed_both(
    db: String,
    bodies: &[ExportTraceServiceRequest],
    spans: u64,
    tag: &str,
) -> (String, ChClient) {
    let client = fresh_db(&db).await;
    land_both(&client, &db, bodies, tag).await;
    let new = count(&client, &format!("SELECT count() AS n FROM {SPANS_TABLE}")).await;
    let old = count(&client, "SELECT count() AS n FROM trace_spans").await;
    assert_eq!(
        (new, old),
        (spans, spans),
        "{db}: spans in the new and the old store"
    );
    (db, client)
}

/// Section 8.3: the search statement answers as today's engine does.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn search_statement_answers_as_today_on_fixture_c() {
    skip_unless_live!();
    let base_ns = (now_ns() / 1_000_000_000) * 1_000_000_000;
    let window = (base_ns, base_ns + CATALOGUE_WINDOW_NS);
    let (db_c, client_c) = seed_both(
        pulsus_testkit::test_db("pulsus_read_it_t591_both_c"),
        &fixture_catalogue_bodies(base_ns),
        34,
        "t591-c",
    )
    .await;
    let (db_z, client_z) = seed_both(
        pulsus_testkit::test_db("pulsus_read_it_t591_both_rz"),
        &[fixture_rz_body(base_ns)],
        6,
        "t591-rz",
    )
    .await;
    let (db_b, client_b) = seed_both(
        pulsus_testkit::test_db("pulsus_read_it_t591_both_b"),
        &fixture_b_bodies(base_ns),
        8,
        "t591-b",
    )
    .await;
    let (db_p, client_p) = seed_both(
        pulsus_testkit::test_db("pulsus_read_it_t591_both_p"),
        &[fixture_p_body(base_ns)],
        3,
        "t591-p",
    )
    .await;

    let mut cases: Vec<(String, &str, &ChClient)> = Vec::new();
    for name in CORPUS_QUERIES {
        cases.push((corpus_query(name), db_c.as_str(), &client_c));
    }
    for q in CATALOGUE_QUERIES {
        cases.push((q.to_string(), db_c.as_str(), &client_c));
    }
    for q in RZ_QUERIES {
        cases.push((q.to_string(), db_z.as_str(), &client_z));
    }
    for q in B_QUERIES {
        cases.push((q.to_string(), db_b.as_str(), &client_b));
    }
    for q in P_QUERIES {
        cases.push((q.to_string(), db_p.as_str(), &client_p));
    }
    let mut mismatches: Vec<String> = Vec::new();
    for (query, db, client) in &cases {
        let parsed = parse_query(query);
        for (limit, spss) in LIMIT_SPSS {
            let want = today(db, &parsed, window, limit, spss)
                .await
                .map(normalise_today);
            let got = statement(client, &parsed, window, limit, spss).await;
            if want != got {
                let show = |r: &Result<pulsus_read::traces::SearchOutput, String>| {
                    let text = format!("{r:?}");
                    text.chars().take(3000).collect::<String>()
                };
                mismatches.push(format!(
                    "{query} (limit {limit}, spss {spss})\n  today:     {}\n  statement: {}",
                    show(&want),
                    show(&got)
                ));
            }
        }
    }
    for db in [&db_c, &db_z, &db_b, &db_p] {
        drop_db(db).await;
    }
    eprintln!("compared {} queries × 3", cases.len());
    assert_eq!(
        cases.len(),
        172,
        "82 corpus, 42 catalogue, 8 RZ, 3 B and 37 P queries"
    );
    assert!(
        mismatches.is_empty(),
        "{} of {} comparisons differ:\n\n{}",
        mismatches.len(),
        cases.len() * 3,
        mismatches.join("\n\n")
    );
}

/// The last four hex digits of an id.
fn tail4(id: &[u8]) -> String {
    let hex: String = id.iter().map(|b| format!("{b:02x}")).collect();
    hex[hex.len() - 4..].to_string()
}

fn value_text(v: &pulsus_read::traces::GroupValue) -> String {
    use pulsus_read::traces::GroupValue;
    match v {
        GroupValue::Str(s) => format!("Str {s}"),
        GroupValue::Int(i) => format!("Int {i}"),
        GroupValue::Double(bits) => format!("Double {:?}", f64::from_bits(*bits)),
        GroupValue::Bool(b) => format!("Bool {b}"),
        GroupValue::Nil => "Nil".to_string(),
    }
}

/// An answer written as section 8.4 writes it: `TTTT(m): SSSS…` per trace,
/// `|` between traces; each span `SSSS`, then `{name="…"}` when a name is
/// projected, then `[key=Kind value,…]` when attributes are. With `ids_only`
/// a span is its `SSSS` alone and a trace's spans are listed by id, as
/// section 8.4's table lists them; otherwise in the answer's order.
fn written(out: &pulsus_read::traces::SearchOutput, ids_only: bool) -> String {
    out.traces
        .iter()
        .map(|t| {
            let mut spans: Vec<String> = t
                .spans
                .iter()
                .map(|s| {
                    let mut text = tail4(&s.span_id);
                    if ids_only {
                        return text;
                    }
                    if let Some(name) = s.name() {
                        text.push_str(&format!("{{name={name:?}}}"));
                    }
                    if !s.attributes.is_empty() {
                        let attrs: Vec<String> = s
                            .attributes
                            .iter()
                            .map(|a| format!("{}={}", a.key(), value_text(a.value())))
                            .collect();
                        text.push_str(&format!("[{}]", attrs.join(",")));
                    }
                    text
                })
                .collect();
            if ids_only {
                spans.sort();
            }
            format!("{}({}): {}", tail4(&t.trace_id), t.matched, spans.join(" "))
        })
        .collect::<Vec<_>>()
        .join(" | ")
}

/// `query`'s decoded answer from the search statement, `limit` and `spss`
/// 100.
async fn ask(
    client: &ChClient,
    query: &str,
    window: (i64, i64),
) -> pulsus_read::traces::SearchOutput {
    statement(client, &parse_query(query), window, 100, 100)
        .await
        .unwrap_or_else(|e| panic!("{query}: {e}"))
}

/// Records a written answer that differs.
fn check(wrong: &mut Vec<String>, label: &str, got: String, want: &str) {
    if got != want {
        wrong.push(format!("{label}\n  want: {want}\n  got:  {got}"));
    }
}

/// Section 8.4: answers written from the fixtures' own tables, by neither
/// engine.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn search_statement_answers_written_out_on_fixture_c() {
    skip_unless_live!();
    let base_ns = (now_ns() / 1_000_000_000) * 1_000_000_000;
    let window = (base_ns, base_ns + CATALOGUE_WINDOW_NS);
    let db_c = pulsus_testkit::test_db("pulsus_read_it_t591_written_c");
    let client_c = fresh_db(&db_c).await;
    for (i, req) in fixture_catalogue_bodies(base_ns).into_iter().enumerate() {
        land(&client_c, &req, &format!("t591w-c-{i}-{}", now_ns())).await;
    }
    let db_z = pulsus_testkit::test_db("pulsus_read_it_t591_written_rz");
    let client_z = fresh_db(&db_z).await;
    land(
        &client_z,
        &fixture_rz_body(base_ns),
        &format!("t591w-rz-{}", now_ns()),
    )
    .await;
    let db_b = pulsus_testkit::test_db("pulsus_read_it_t591_written_b");
    let client_b = fresh_db(&db_b).await;
    for (i, req) in fixture_b_bodies(base_ns).into_iter().enumerate() {
        land(&client_b, &req, &format!("t591w-b-{i}-{}", now_ns())).await;
    }
    for (client, want) in [(&client_c, 34), (&client_z, 6), (&client_b, 8)] {
        let n = count(client, &format!("SELECT count() AS n FROM {SPANS_TABLE}")).await;
        assert_eq!(n, want, "seeded spans");
    }

    let mut wrong: Vec<String> = Vec::new();
    let full = [
        (
            r#"{ span.a = 1 }"#,
            "6666(1): 002d[a=Int 1] | 5555(1): 001e[a=Int 1] | 4444(4): 0015[a=Int 1] \
             0017[a=Int 1] 0019[a=Int 1] 0020[a=Int 1] | 2222(2): 0004[a=Int 1] 0005[a=Int 1] \
             | 1111(2): 0001[a=Int 1] 0003[a=Double 1.0]",
        ),
        (
            r#"{ span.foo != nil }"#,
            "6666(1): 002d[foo=Bool true] | 1111(1): 0001[foo=Str f]",
        ),
        (
            r#"{ name = "b" }"#,
            "6666(1): 002d{name=\"b\"} | 1111(1): 0002{name=\"b\"}",
        ),
        (
            r#"{ span.a / 2 > 1 }"#,
            "6666(2): 0029[a=Int 8] 002b[a=Int 6] | 3333(1): 0008[a=Double 2.5]",
        ),
        (
            r#"{ span.c = 3 } || ({ span.a = 1 } && { span.zzz = 1 })"#,
            "2222(1): 0006[c=Int 3] | 1111(2): 0002[c=Int 3] 0003[c=Int 3,a=Double 1.0]",
        ),
    ];
    for (query, want) in full {
        check(
            &mut wrong,
            query,
            written(&ask(&client_c, query, window).await, false),
            want,
        );
    }
    let ids = [
        (
            r#"{ span.a = 1 } && { span.b = 2 }"#,
            "6666(2): 002a 002d | 5555(2): 001e 001f | 4444(9): 0015 0016 0017 0019 001a 001b \
             0020 0021 0024 | 2222(2): 0004 0005 | 1111(3): 0001 0002 0003",
        ),
        (
            r#"{ span.a = 1 } || { name = "bare" }"#,
            "6666(1): 002d | 5555(1): 001e | 4444(4): 0015 0017 0019 0020 | 3333(1): 0007 | \
             2222(2): 0004 0005 | 1111(2): 0001 0003",
        ),
        (
            r#"{ span.a = 1 } || { span.b = 2 } && { span.c = 3 }"#,
            "2222(3): 0004 0005 0006 | 1111(3): 0001 0002 0003",
        ),
    ];
    for (query, want) in ids {
        check(
            &mut wrong,
            query,
            written(&ask(&client_c, query, window).await, true),
            want,
        );
    }
    let all = ask(&client_c, "{}", window).await;
    let t5 = all
        .traces
        .iter()
        .find(|t| t.trace_id == [0x55; 16])
        .expect("trace 5555 is returned");
    check(
        &mut wrong,
        "{} trace 5555 root",
        format!("{:?}", (&t5.root.service, &t5.root.name)),
        "(\"\", \"\")",
    );

    let z = ask(&client_z, "{}", window).await;
    let aa = z
        .traces
        .iter()
        .find(|t| t.trace_id == [0xaa; 16])
        .expect("trace aa is returned");
    check(
        &mut wrong,
        "z01 {} trace aa root",
        format!("{:?}", (&aa.root.service, &aa.root.name)),
        "(\"svc-a\", \"z-name\")",
    );
    for (query, want) in [
        (
            r#"{ span.tags != nil }"#,
            "bbbb(1): 00b1[tags=Str [\"gold\",\"eu\"]]",
        ),
        (
            r#"{ span.floats != nil }"#,
            "bbbb(1): 00b1[floats=Str [1.5,2.0]]",
        ),
        (
            r#"{ span.a / 2 > 1 }"#,
            "bbbb(2): 00b2[a=Int 8] 00b3[a=Double 2.5]",
        ),
        (
            r#"{ span.a % 5 = 3 }"#,
            "bbbb(2): 00b1[a=Int 3] 00b2[a=Int 8]",
        ),
        (r#"{ span.a ^ 2 > 10 }"#, "bbbb(1): 00b2[a=Int 8]"),
    ] {
        check(
            &mut wrong,
            query,
            written(&ask(&client_z, query, window).await, false),
            want,
        );
    }

    // Decision 10's boundary: a value at 8,192 bytes comes back whole; one
    // at 8,193 bytes as its first 2,048 code points.
    let n = |count: usize| "n".repeat(count);
    let b_roots = ask(&client_b, "{}", window).await;
    let root_of = |trace: u8| {
        let t = b_roots
            .traces
            .iter()
            .find(|t| t.trace_id == [trace; 16])
            .unwrap_or_else(|| panic!("trace {trace:02x} is returned"));
        (t.root.service.clone(), t.root.name.clone())
    };
    let boundary = [
        ("f1 root name", root_of(0xf1).1, n(8192)),
        ("f2 root name", root_of(0xf2).1, n(2048)),
        (
            "f3 root service",
            root_of(0xf3).0,
            format!("{}nn", "日".repeat(2730)),
        ),
        ("f4 root service", root_of(0xf4).0, "日".repeat(2048)),
    ];
    for (label, got, want) in boundary {
        check(
            &mut wrong,
            label,
            format!("{} bytes", got.len()),
            &format!("{} bytes", want.len()),
        );
        if got != want {
            wrong.push(format!("{label}: the value differs"));
        }
    }
    let projected_of = |out: &pulsus_read::traces::SearchOutput, trace: u8| -> String {
        let t = out
            .traces
            .iter()
            .find(|t| t.trace_id == [trace; 16])
            .unwrap_or_else(|| panic!("trace {trace:02x} is returned"));
        match t.spans[0].attributes[0].value() {
            pulsus_read::traces::GroupValue::Str(s) => s.clone(),
            other => panic!("{other:?}"),
        }
    };
    let s = ask(&client_b, r#"{ span.s =~ ".+" }"#, window).await;
    let arr = ask(&client_b, r#"{ span.arr != nil }"#, window).await;
    let arr7 = format!("[\"{}\"]", n(8188));
    let arr8: String = format!("[\"{}\"]", n(8189)).chars().take(2048).collect();
    for (label, got, want) in [
        ("f5 span.s", projected_of(&s, 0xf5), n(8192)),
        ("f6 span.s", projected_of(&s, 0xf6), n(2048)),
        ("f7 span.arr", projected_of(&arr, 0xf7), arr7),
        ("f8 span.arr", projected_of(&arr, 0xf8), arr8),
    ] {
        if got != want {
            wrong.push(format!(
                "{label}: {} bytes back, {} expected",
                got.len(),
                want.len()
            ));
        }
    }
    for db in [&db_c, &db_z, &db_b] {
        drop_db(db).await;
    }
    assert!(
        wrong.is_empty(),
        "{} written answer(s) differ:\n\n{}",
        wrong.len(),
        wrong.join("\n\n")
    );
}

/// Issue #591 part 2's section 7.3: fixture P's answers written from its
/// own table, by neither engine; `limit` and `spss` 100.
///
/// Then fixture S's two-element sets, `[2, 5]`: `/`, `%` and `^` over an
/// event, link or unscoped field, and a set field compared with itself by
/// `<` or `>`. Each ranges over the set's elements, as
/// `docs/benchmarks/traces-differential-ledger.md`,
/// `traceql-event-link-set-operands`, records ("arithmetic over event, link
/// and unscoped operands ranges over their elements"; "two sets are
/// compared pair by pair"). Today's engine reads the first element, `2`,
/// and answers none of these: they are a documented difference, not
/// parity, so neither engine wrote these rows either.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn search_statement_answers_written_out_on_fixture_p() {
    skip_unless_live!();
    let base_ns = (now_ns() / 1_000_000_000) * 1_000_000_000;
    let window = (base_ns, base_ns + CATALOGUE_WINDOW_NS);
    let db_p = pulsus_testkit::test_db("pulsus_read_it_t591_written_p");
    let client_p = fresh_db(&db_p).await;
    land(
        &client_p,
        &fixture_p_body(base_ns),
        &format!("t591w-p-{}", now_ns()),
    )
    .await;
    let db_s = pulsus_testkit::test_db("pulsus_read_it_t591_written_s");
    let client_s = fresh_db(&db_s).await;
    land(
        &client_s,
        &fixture_s_body(base_ns),
        &format!("t591w-s-{}", now_ns()),
    )
    .await;
    for (client, want) in [(&client_p, 3), (&client_s, 1)] {
        let n = count(client, &format!("SELECT count() AS n FROM {SPANS_TABLE}")).await;
        assert_eq!(n, want, "seeded spans");
    }

    let mut wrong: Vec<String> = Vec::new();
    let p_rows = [
        // q02
        (r#"{ resource.rk_i > 5 }"#, "1111(1): 0001[rk_i=Int 7]"),
        // q05: the stored array's JSON, not `['x','y']`.
        (
            r#"{ resource.rk_arr != nil }"#,
            "1111(1): 0001[rk_arr=Str [\"x\",\"y\"]]",
        ),
        // q07: the first element whose own condition holds — not the first
        // carrying `k` (1), nor the last (9).
        (
            r#"{ event.k > 3 }"#,
            "2222(1): 0003[k=Double 4.5] | 1111(1): 0001[k=Int 5]",
        ),
        // q10
        (
            r#"{ event.k != nil }"#,
            "2222(1): 0003[k=Double 4.5] | 1111(2): 0001[k=Int 1] 0002[k=Int 3]",
        ),
        // q13
        (
            r#"{ event:timeSinceStart > 1500us }"#,
            "1111(1): 0001[event:timeSinceStart=Int 2000000]",
        ),
        // q18
        (
            r#"{ .p != nil }"#,
            "2222(1): 0003[p=Int 42] | 1111(2): 0001[p=Str res] 0002[p=Int 42]",
        ),
        // q19
        (r#"{ .r =~ "ev-r.*" }"#, "1111(1): 0001[r=Str ev-r1]"),
        // q20: the link before the instrumentation scope.
        (r#"{ .s =~ "link.*" }"#, "1111(1): 0001[s=Str link-s1]"),
        // q22: the span's own `k` before the event's on `…03`; `…02`'s
        // string `"span-k"` is not compared with `2`.
        (
            r#"{ .k > 2 }"#,
            "2222(1): 0003[k=Double 2.5] | 1111(1): 0001[k=Int 5]",
        ),
        // q23
        (
            r#"{ .k != nil }"#,
            "2222(1): 0003[k=Double 2.5] | 1111(2): 0001[k=Int 1] 0002[k=Str span-k]",
        ),
        // q27: the literal, lowercased.
        (
            r#"{ link:spanID = "0B00000000000002" }"#,
            "1111(1): 0001[link:spanID=Str 0b00000000000002]",
        ),
        // q29
        (
            r#"{ .t != nil }"#,
            "2222(1): 0003[t=Str [\"x\",\"y\"]] | 1111(1): 0001[t=Str a]",
        ),
        // r01: the first element the comparison holds for.
        (
            r#"{ event.k * 2 > 5 }"#,
            "2222(1): 0003[k=Double 4.5] | 1111(2): 0001[k=Int 5] 0002[k=Int 3]",
        ),
        // r02: the span's own `k = 2.5` on `…03` decides, and fails.
        (r#"{ .k * 2 > 5 }"#, "1111(1): 0001[k=Int 5]"),
        // r03: the first element carrying the field.
        (
            r#"{ event.k = event.k }"#,
            "2222(1): 0003[k=Double 4.5] | 1111(2): 0001[k=Int 1] 0002[k=Int 3]",
        ),
        // r04: not `2`, the first link carrying `lk`.
        (r#"{ link.lk - 1 > 4 }"#, "1111(1): 0001[lk=Int 6]"),
        // r05
        (
            r#"{ event:timeSinceStart * 2 > 3ms }"#,
            "1111(1): 0001[event:timeSinceStart=Int 2000000]",
        ),
        // r06
        (
            r#"{ .k = .k }"#,
            "2222(1): 0003[k=Double 2.5] | 1111(2): 0001[k=Int 1] 0002[k=Str span-k]",
        ),
        // r07: the first link carrying `lk`.
        (r#"{ link.lk = link.lk }"#, "1111(1): 0001[lk=Int 2]"),
        // r08
        (
            r#"{ .p * 2 > 50 }"#,
            "2222(1): 0003[p=Int 42] | 1111(1): 0002[p=Int 42]",
        ),
        // r09
        (
            r#"{ event:name = event:name }"#,
            "2222(1): 0003[event:name=Str beta] | 1111(2): 0001[event:name=Str alpha] \
             0002[event:name=Str delta]",
        ),
    ];
    for (query, want) in p_rows {
        check(
            &mut wrong,
            query,
            written(&ask(&client_p, query, window).await, false),
            want,
        );
    }
    // Section 3.6's refusal holds under `!=` too: on fixture P the
    // predicate's any-pair reading drops span `…01`, which today's engine,
    // reading each element against itself, returns. The statement refuses,
    // so the query is today's engine's.
    for query in [r#"{ event.k * event.k != 5 }"#, r#"{ .k + 1 != .k }"#] {
        match statement(&client_p, &parse_query(query), window, 100, 100).await {
            Err(e) if e.contains("two occurrences") => {}
            other => wrong.push(format!(
                "{query}\n  want: a refusal naming two occurrences\n  got:  {:?}",
                other.map(|o| written(&o, false))
            )),
        }
    }
    let five = |key: &str| format!("3333(1): 0004[{key}=Int 5]");
    let two = |key: &str| format!("3333(1): 0004[{key}=Int 2]");
    let s_rows = [
        (r#"{ event.k / 5 >= 1 }"#, five("k")),
        (r#"{ event.k % 2 = 1 }"#, five("k")),
        (r#"{ event.k ^ 2 > 10 }"#, five("k")),
        (r#"{ link.lk / 5 >= 1 }"#, five("lk")),
        (r#"{ link.lk % 2 = 1 }"#, five("lk")),
        (r#"{ link.lk ^ 2 > 10 }"#, five("lk")),
        (r#"{ .k / 5 >= 1 }"#, five("k")),
        (r#"{ .k % 2 = 1 }"#, five("k")),
        (r#"{ .k ^ 2 > 10 }"#, five("k")),
        // A set field compared with itself projects the first element
        // carrying it; `2 < 5` and `5 > 2` are the pairs that hold.
        (r#"{ event.k < event.k }"#, two("k")),
        (r#"{ event.k > event.k }"#, two("k")),
        (r#"{ link.lk < link.lk }"#, two("lk")),
        (r#"{ link.lk > link.lk }"#, two("lk")),
        (r#"{ .k < .k }"#, two("k")),
        (r#"{ .k > .k }"#, two("k")),
    ];
    for (query, want) in s_rows {
        check(
            &mut wrong,
            query,
            written(&ask(&client_s, query, window).await, false),
            &want,
        );
    }
    for db in [&db_p, &db_s] {
        drop_db(db).await;
    }
    assert!(
        wrong.is_empty(),
        "{} written answer(s) differ:\n\n{}",
        wrong.len(),
        wrong.join("\n\n")
    );
}

/// Section 8.4's fixture R2: roots arriving in two pushes, across a UTC
/// midnight and within one day, read before and after the per-trace
/// table's parts merge.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn search_statement_reads_one_root_across_pushes_and_merges() {
    skip_unless_live!();
    const S: i64 = 1_000_000_000;
    const DAY: i64 = 86_400 * S;
    let midnight = (now_ns() / DAY) * DAY;
    let db = pulsus_testkit::test_db("pulsus_read_it_t591_r2");
    let client = fresh_db(&db).await;
    let sp = |trace: u8, span: u8, parent: u8, at: i64| {
        span_of(
            vec![trace; 16],
            vec![0, 0, 0, 0, 0, 0, 0, span],
            if parent == 0 {
                Vec::new()
            } else {
                vec![0, 0, 0, 0, 0, 0, 0, parent]
            },
            "",
            1,
            at,
            1_000_000,
            Vec::new(),
            0,
            Vec::new(),
            Vec::new(),
        )
    };
    let named = |mut span: Span, name: &str| {
        span.name = name.to_string();
        span
    };
    let push = |spans: Vec<(&str, Span)>| ExportTraceServiceRequest {
        resource_spans: spans
            .into_iter()
            .map(|(service, span)| ResourceSpans {
                resource: Some(Resource {
                    attributes: vec![kv("service.name", str_value(service))],
                    dropped_attributes_count: 0,
                    entity_refs: Vec::new(),
                }),
                scope_spans: vec![ScopeSpans {
                    scope: Some(scope_named("io.pulsus.r2", "1.0", Vec::new())),
                    spans: vec![span],
                    schema_url: String::new(),
                }],
                schema_url: String::new(),
            })
            .collect(),
    };
    let push1 = push(vec![
        ("svc-z", named(sp(0xcc, 0xc2, 0, midnight + S), "a-name")),
        (
            "svc-q",
            named(sp(0xcc, 0xc3, 0xc2, midnight + S + 1_000_000), "child"),
        ),
        ("svc-d", named(sp(0xdd, 0xd2, 0xd9, midnight + S), "d-two")),
        (
            "svc-z",
            named(sp(0xee, 0xe2, 0, midnight + 2 * S), "a-name"),
        ),
    ]);
    let push2 = push(vec![
        ("svc-a", named(sp(0xcc, 0xc1, 0, midnight - S), "z-name")),
        ("svc-d", named(sp(0xdd, 0xd1, 0xd9, midnight - S), "d-one")),
        ("svc-a", named(sp(0xee, 0xe1, 0, midnight + S), "z-name")),
    ]);
    land_both(&client, &db, &[push1, push2], "t591-r2").await;
    let n = count(&client, &format!("SELECT count() AS n FROM {SPANS_TABLE}")).await;
    assert_eq!(n, 7, "fixture R2 seeds seven spans");
    let window = (midnight - 60 * S, midnight + 60 * S);
    let roots = |out: &pulsus_read::traces::SearchOutput| -> Vec<(String, String, String)> {
        out.traces
            .iter()
            .map(|t| {
                (
                    format!("{:02x}", t.trace_id[0]),
                    t.root.service.clone(),
                    t.root.name.clone(),
                )
            })
            .collect()
    };
    let want = vec![
        ("ee".to_string(), "svc-a".to_string(), "z-name".to_string()),
        ("cc".to_string(), "svc-a".to_string(), "z-name".to_string()),
        ("dd".to_string(), String::new(), String::new()),
    ];
    let parsed = parse_query("{}");
    let before = roots(
        &statement(&client, &parsed, window, 100, 100)
            .await
            .expect("the statement answers"),
    );
    client
        .execute(
            "OPTIMIZE TABLE traces FINAL",
            &QuerySettings::new(),
            Idempotency::Idempotent,
        )
        .await
        .expect("merge traces");
    let after = roots(
        &statement(&client, &parsed, window, 100, 100)
            .await
            .expect("the statement answers"),
    );
    let ee_rows = client
        .query_stream::<CountRow>(
            "SELECT count() AS n FROM traces WHERE trace_id = toFixedString(unhex(repeat('ee', 16)), 16)",
            &QuerySettings::new(),
        )
        .await
        .expect("count ee")
        .next()
        .await
        .expect("one row")
        .expect("decode")
        .n;
    drop_db(&db).await;
    assert_eq!(before, want, "the roots before the merge");
    assert_eq!(after, want, "the roots after the merge");
    assert_eq!(ee_rows, 1, "trace ee is one row after the merge");
}

// =====================================================================
// Issue #591 part 3 — the route fork
// =====================================================================

/// The engine over `db`, configured as [`today`] configures it.
async fn engine_of(db: &str) -> pulsus_read::TraceEngine {
    pulsus_read::TraceEngine::new(
        ChClient::new(client_config(db))
            .await
            .expect("connect the engine"),
        engine_config(),
    )
}

/// Today's planner's plan for `query` over `w`.
fn plan_of(
    engine: &pulsus_read::TraceEngine,
    query: &pulsus_traceql::Query,
    w: (i64, i64),
    limit: u32,
    spss: u32,
) -> pulsus_read::SearchPlan {
    use pulsus_read::traces::search_plan::{SearchParams, plan_search};
    plan_search(
        query,
        &SearchParams {
            start_ns: w.0,
            end_ns: w.1,
            limit,
            spss,
        },
        &engine.search_ctx(),
    )
    .unwrap_or_else(|e| panic!("{query}: today's planner refused: {e}"))
}

/// Whether the fork's coverage function gives `plan` a statement, with
/// [`engine_config`]'s tables.
fn covered(plan: &pulsus_read::SearchPlan) -> bool {
    pulsus_read::traces::spans::search::plan_statement(
        plan,
        "spans",
        "traces",
        "resources",
        64,
        &[],
    )
    .is_some()
}

/// The inventory's `new` rows, by name.
fn inventory_new_names() -> Vec<String> {
    let path =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/traces_route_inventory.tsv");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {path:?}: {e}"));
    text.lines()
        .skip(1)
        .filter_map(|line| {
            let cols: Vec<&str> = line.split('\t').collect();
            (cols.get(2) == Some(&"new")).then(|| cols[0].to_string())
        })
        .collect()
}

/// Section 6.2: every query the inventory puts on the search statement is
/// covered, and the fork answers it as today's engine does, at three
/// `(limit, spss)` pairs, on fixture C landed in both stores.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn search_routed_answers_as_today_on_fixture_c() {
    skip_unless_live!();
    let base_ns = (now_ns() / 1_000_000_000) * 1_000_000_000;
    let window = (base_ns, base_ns + CATALOGUE_WINDOW_NS);
    let (db, _client) = seed_both(
        pulsus_testkit::test_db("pulsus_read_it_t591p3_fork_c"),
        &fixture_catalogue_bodies(base_ns),
        34,
        "t591p3-c",
    )
    .await;
    let engine = engine_of(&db).await;
    let names = inventory_new_names();
    // The inventory's covered corpus rows, then issue #592 part 1's shapes
    // beyond the corpus.
    let mut cases: Vec<(String, String)> = names
        .iter()
        .map(|name| (name.clone(), corpus_query(name)))
        .collect();
    for shape in PIPELINE_SHAPES_BEYOND_THE_CORPUS {
        cases.push((shape.to_string(), shape.to_string()));
    }
    let mut wrong: Vec<String> = Vec::new();
    for (name, text) in &cases {
        let parsed = parse_query(text);
        for (limit, spss) in LIMIT_SPSS {
            let plan = plan_of(&engine, &parsed, window, limit, spss);
            if !covered(&plan) {
                wrong.push(format!("{name} (limit {limit}, spss {spss}): not covered"));
                continue;
            }
            let want = engine.search(&plan).await.map(normalise_today);
            let got = engine.search_routed(&plan).await;
            let (want, got) = (format!("{want:?}"), format!("{got:?}"));
            if want != got {
                wrong.push(format!(
                    "{name} (limit {limit}, spss {spss})\n  today:  {}\n  routed: {}",
                    want.chars().take(2000).collect::<String>(),
                    got.chars().take(2000).collect::<String>()
                ));
            }
        }
    }
    drop_db(&db).await;
    eprintln!("compared {} × 3", cases.len());
    // Issue #592 part 1's three small fixtures, each in its own database:
    // every case must equal today's answer and its literal answer.
    let mut fixture_cases = 0usize;
    for (label, bodies, spans, cases) in pipeline_fixtures(base_ns) {
        let (db, _client) = seed_both(
            pulsus_testkit::test_db(&format!("pulsus_read_it_t592p1_{label}")),
            &bodies,
            spans,
            &format!("t592p1-{label}"),
        )
        .await;
        let engine = engine_of(&db).await;
        for (query, limit, spss, literal) in cases {
            fixture_cases += 1;
            let ctx = format!("{label}: {query} (limit {limit}, spss {spss})");
            let plan = plan_of(&engine, &parse_query(query), window, limit, spss);
            if !covered(&plan) {
                wrong.push(format!("{ctx}: not covered"));
                continue;
            }
            let today = engine.search(&plan).await.map(normalise_today);
            let routed = engine.search_routed(&plan).await;
            if format!("{today:?}") != format!("{routed:?}") {
                wrong.push(format!(
                    "{ctx}\n  today:  {}\n  routed: {}",
                    answer_of(&today),
                    answer_of(&routed)
                ));
                continue;
            }
            if answer_of(&routed) != literal {
                wrong.push(format!(
                    "{ctx}\n  literal: {literal}\n  both:    {}",
                    answer_of(&routed)
                ));
            }
        }
        drop_db(&db).await;
    }
    eprintln!("and {fixture_cases} fixture cases");
    assert_eq!(names.len(), 116, "the inventory's new rows");
    assert!(
        wrong.is_empty(),
        "{} of {} differ:\n\n{}",
        wrong.len(),
        cases.len() * 3 + fixture_cases,
        wrong.join("\n\n")
    );
}

/// An answer as `(trace, matched, span ids)` per trace, in order, each id
/// by its last byte in hex: `a1 1 [01]; b2 1 [03]`.
fn answer_of(
    out: &Result<pulsus_read::traces::SearchOutput, pulsus_read::logql::ReadError>,
) -> String {
    match out {
        Err(e) => format!("Err({e})"),
        Ok(o) => o
            .traces
            .iter()
            .map(|t| {
                let spans: Vec<String> = t
                    .spans
                    .iter()
                    .map(|s| format!("{:02x}", s.span_id[7]))
                    .collect();
                format!(
                    "{:02x} {} [{}]",
                    t.trace_id[15],
                    t.matched,
                    spans.join(", ")
                )
            })
            .collect::<Vec<_>>()
            .join("; "),
    }
}

/// One fixture of [`pipeline_fixtures`]: its label, its bodies, its span
/// count, and its cases `(query, limit, spss, literal answer)`.
type PipelineFixture = (
    &'static str,
    Vec<ExportTraceServiceRequest>,
    u64,
    Vec<(&'static str, u32, u32, &'static str)>,
);

/// Issue #592 part 1's three small fixtures. Every span has kind server,
/// a 0.1 s duration and no attributes, and the resource
/// `service.name = "svc"` unless said otherwise; starts are seconds after
/// `base_ns`.
///
/// - `rank`: today's engine ranks a trace by the newest span the
///   selector matched, before any stage runs. `a1`'s newest span (+10 s)
///   is removed by the later filter, and `a1` still comes first.
/// - `cap`: `c1` and `c2` tie at +20 s, and the lower trace id comes
///   first; `c1` keeps four spans and returns three; spans 12 and 13
///   start together and come in span-id order.
/// - `noservice`: `d1`'s span is in a resource with no attributes, and
///   `select(resource.service.name)` returns its service as `""`, as
///   today's engine does.
fn pipeline_fixtures(base_ns: i64) -> Vec<PipelineFixture> {
    const S: i64 = 1_000_000_000;
    let sp = |trace: u8, span: u8, name: &str, at_s: i64| {
        span_of(
            vec![trace; 16],
            vec![0, 0, 0, 0, 0, 0, 0, span],
            Vec::new(),
            name,
            2,
            base_ns + at_s * S,
            S / 10,
            Vec::new(),
            0,
            Vec::new(),
            Vec::new(),
        )
    };
    let body = |attributes: Vec<KeyValue>, spans: Vec<Span>| ExportTraceServiceRequest {
        resource_spans: vec![ResourceSpans {
            resource: Some(Resource {
                attributes,
                dropped_attributes_count: 0,
                entity_refs: Vec::new(),
            }),
            scope_spans: vec![ScopeSpans {
                scope: Some(scope()),
                spans,
                schema_url: String::new(),
            }],
            schema_url: String::new(),
        }],
    };
    let svc = || vec![kv("service.name", str_value("svc"))];
    let later = r#"{ } | { name = "b" }"#;
    vec![
        (
            "rank",
            vec![body(
                svc(),
                vec![
                    sp(0xa1, 1, "b", 1),
                    sp(0xa1, 2, "c", 10),
                    sp(0xb2, 3, "b", 5),
                ],
            )],
            3,
            vec![
                (later, 1, 3, "a1 1 [01]"),
                (later, 20, 3, "a1 1 [01]; b2 1 [03]"),
            ],
        ),
        (
            "cap",
            vec![body(
                svc(),
                vec![
                    sp(0xc1, 11, "b", 1),
                    sp(0xc1, 13, "b", 2),
                    sp(0xc1, 12, "b", 2),
                    sp(0xc1, 14, "b", 3),
                    sp(0xc1, 15, "c", 20),
                    sp(0xc2, 21, "b", 4),
                    sp(0xc2, 22, "c", 20),
                ],
            )],
            7,
            vec![
                (later, 1, 3, "c1 4 [0b, 0c, 0d]"),
                (later, 20, 3, "c1 4 [0b, 0c, 0d]; c2 1 [15]"),
            ],
        ),
        (
            "noservice",
            vec![
                body(Vec::new(), vec![sp(0xd1, 31, "b", 2)]),
                body(svc(), vec![sp(0xd2, 32, "b", 1)]),
            ],
            2,
            vec![(
                r#"{ } | select(resource.service.name)"#,
                20,
                3,
                "d1 1 [1f]; d2 1 [20]",
            )],
        ),
    ]
}

/// Issue #592 part 1's pipeline shapes beyond the corpus: later `{…}`
/// filters and `select()` after a single filter, and part 2's `by()` and
/// `coalesce()`, each answered by the search statement as by today's
/// engine on fixture C.
const PIPELINE_SHAPES_BEYOND_THE_CORPUS: [&str; 22] = [
    "{ } | sum(span.a) > 0",
    "{ } | min(span.a) < 100",
    "{ } | max(span.a) > 0",
    "{ } | avg(span.a) > 0",
    "{ } | avg(duration) > 1ms",
    "{ } | min(.a) < 10",
    "{ } | count() > 2 | coalesce()",
    r#"{ } | { status = error } | count() > 1 | select(span.a)"#,
    // One field per scope read off the span row: span `…0004` holds all
    // four, so a scope read from the wrong place changes the answer.
    r#"{ } | select(event.exception.type, link.relation, resource.k8s.pod.name, instrumentation.otel.scope.build)"#,
    r#"{ } | { name = "b" }"#,
    r#"{ } | { .a = 1 } | { name = "b" }"#,
    r#"{ .a = 1 } | select(.a) | { }"#,
    r#"{ status = error } | select(status)"#,
    r#"{ } | select(status, kind, duration, span:id, trace:id)"#,
    r#"{ } | select(.a, span.a, resource.service.name)"#,
    // Issue #592 part 2.
    r#"{ } | by(span.a)"#,
    r#"{ } | by(name)"#,
    r#"{ } | by(status) | { .a = 1 }"#,
    r#"{ } | by(kind) | select(span.a)"#,
    r#"{ } | by(span.success)"#,
    r#"{ } | by(span.a) | coalesce()"#,
    r#"{ } | by(span.a) | coalesce() | { name = "b" }"#,
];

/// `T-C1`'s sixteen non-structural filters of
/// `docs/TraceQL/measure/agreement.py`, by their ground-truth row.
const T_C1_FILTERS: [(&str, &str); 16] = [
    ("service", r#"{ resource.service.name = "checkout" }"#),
    (
        "service_error",
        r#"{ resource.service.name = "payment" && status = error }"#,
    ),
    (
        "status_code_ge_500",
        r#"{ span.http.response.status_code >= 500 }"#,
    ),
    ("duration_kind", r#"{ duration > 2s && kind = server }"#),
    (
        "db_and_name",
        r#"{ span.db.system.name = "postgresql" && name = "SELECT shop" }"#,
    ),
    ("route_regex", r#"{ span.http.route =~ "/api/auth/.*" }"#),
    ("user_point", r#"{ span.app.user.id = "u-10013" }"#),
    (
        "event_attr",
        r#"{ event.exception.type = "java.lang.IllegalStateException" }"#,
    ),
    ("bool_true", r#"{ span.app.cache.hit = true }"#),
    ("float_gt", r#"{ span.app.discount.ratio > 0.4 }"#),
    ("int_ne", r#"{ span.http.response.status_code != 200 }"#),
    ("array_attr", r#"{ span.app.tags = "gold" }"#),
    ("kind_producer", r#"{ kind = producer }"#),
    ("status_unset", r#"{ status = unset }"#),
    ("name_eq", r#"{ name = "SELECT shop" }"#),
    (
        "resource_attr",
        r#"{ resource.k8s.pod.name = "cart-7d9f8b-00002" }"#,
    ),
];

/// `T-C1`: over g1, the sixteen non-structural filters count what
/// `docs/TraceQL/measure/results/g1-ground-truth.tsv` records. g1 is built
/// by hand (section 6.3 of #591 part 3's design) into the database
/// `PULSUS_TEST_G1_DATABASE` names; the test is run by name and panics,
/// never skips green, without it. The window is g1's own: its first span's
/// start to one past its last.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
#[ignore = "needs g1, built by hand: see the doc comment"]
async fn t_c1_the_sixteen_filters_equal_the_ground_truth_on_g1() {
    let db = std::env::var("PULSUS_TEST_G1_DATABASE")
        .expect("PULSUS_TEST_G1_DATABASE names the database g1 was built in");
    let client = ChClient::new(ChConnConfig {
        database: db.clone(),
        ..base_config()
    })
    .await
    .expect("connect to g1");
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../docs/TraceQL/measure/results/g1-ground-truth.tsv");
    let truth = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {path:?}: {e}"));
    let truth: std::collections::HashMap<&str, u64> = truth
        .lines()
        .skip(1)
        .filter_map(|line| {
            let (case, n) = line.split_once('\t')?;
            Some((case, n.trim().parse().ok()?))
        })
        .collect();
    let first = count(
        &client,
        &format!("SELECT min(start_ns) AS n FROM {SPANS_TABLE}"),
    )
    .await;
    let last = count(
        &client,
        &format!("SELECT max(start_ns) AS n FROM {SPANS_TABLE}"),
    )
    .await;
    let w = WindowSql::start_closed_end_open(first as i64, last as i64 + 1);
    let mut wrong = Vec::new();
    for (case, query) in T_C1_FILTERS {
        let want = *truth
            .get(case)
            .unwrap_or_else(|| panic!("{case} has a ground-truth row"));
        let p = compile_span_predicate_in(&body(query), &ctx_of(w))
            .unwrap_or_else(|e| panic!("{query}: {e}"));
        let got = count(
            &client,
            &format!(
                "SELECT count() AS n FROM {SPANS_TABLE} WHERE {} AND {} AND {} AND ({})",
                w.span_time_clause(),
                w.span_bucket_clause(),
                w.span_day_clause(),
                p.sql()
            ),
        )
        .await;
        eprintln!("{case}: {got} (ground truth {want})");
        if got != want {
            wrong.push(format!("{case}: {got}, ground truth {want}"));
        }
    }
    assert!(wrong.is_empty(), "{}", wrong.join("\n"));
}

/// Reads `system.query_log` for `db`'s finished `SELECT`s since `t0_ns`,
/// read twice a second apart until two reads agree on a non-zero count:
/// `(statements, rows returned)`.
async fn settled_statements(client: &ChClient, db: &str, t0_ns: i64) -> (u64, u64) {
    #[derive(Row, serde::Serialize, serde::Deserialize, Debug, PartialEq, Clone, Copy)]
    struct Logged {
        n: u64,
        rows: u64,
    }
    let read = || async {
        client
            .execute(
                "SYSTEM FLUSH LOGS",
                &QuerySettings::new(),
                Idempotency::Idempotent,
            )
            .await
            .expect("flush the logs");
        let sql = format!(
            "SELECT count() AS n, sum(result_rows) AS rows FROM system.query_log \
             WHERE type = 'QueryFinish' AND query_kind = 'Select' AND has(databases, '{db}') \
             AND event_time_microseconds >= toDateTime64({}, 6)",
            t0_ns as f64 / 1e9
        );
        let mut stream = client
            .query_stream::<Logged>(&sql, &QuerySettings::new())
            .await
            .expect("read the query log");
        stream
            .next()
            .await
            .expect("one row")
            .expect("decode the query log row")
    };
    let deadline = std::time::Instant::now() + StdDuration::from_secs(30);
    loop {
        let a = read().await;
        tokio::time::sleep(StdDuration::from_secs(1)).await;
        let b = read().await;
        if a == b && a.n >= 1 {
            return (a.n, a.rows);
        }
        assert!(
            std::time::Instant::now() < deadline,
            "the query log did not settle within 30 s: {a:?} then {b:?}"
        );
    }
}

/// `T-Q2`: `{ status = error }` through the fork is one statement, which
/// returns no more rows than `limit`.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn t_q2_a_covered_search_is_one_statement_returning_at_most_limit_rows() {
    skip_unless_live!();
    let (db, client, w) = seed_corpus_s(pulsus_testkit::test_db("pulsus_read_it_t591p3_tq2")).await;
    let engine = engine_of(&db).await;
    let window = (w.first_included_ns(), w.last_included_ns() + 1);
    let plan = plan_of(&engine, &parse_query("{ status = error }"), window, 20, 3);
    let t0 = now_ns();
    let out = engine.search_routed(&plan).await;
    let (n, rows) = settled_statements(&client, &db, t0).await;
    drop_db(&db).await;
    let out = out.expect("the search answers");
    assert_eq!(out.traces.len(), 20, "twenty traces");
    assert_eq!(n, 1, "one statement");
    assert!(rows <= 20, "{rows} rows returned, more than limit");
}

/// The search's error, or its trace and span counts.
fn shape(out: &Result<pulsus_read::traces::SearchOutput, pulsus_read::logql::ReadError>) -> String {
    match out {
        Ok(o) => format!(
            "Ok({} traces, {} spans)",
            o.traces.len(),
            o.traces.iter().map(|t| t.spans.len()).sum::<usize>()
        ),
        Err(e) => format!("Err({e:?})"),
    }
}

/// Section 6.8: on the covered path the search keeps its documented
/// bounds — the result ceiling refuses an answer past 64 MiB with the
/// read/result byte `422`, and an answer that fits is whole.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn search_routed_keeps_the_search_bounds() {
    skip_unless_live!();
    let (db, _client, w) =
        seed_corpus_s(pulsus_testkit::test_db("pulsus_read_it_t591p3_bounds")).await;
    let engine = engine_of(&db).await;
    let window = (w.first_included_ns(), w.last_included_ns() + 1);
    let ceiling = "Err(QueryTooBroad(ScanBudgetBytes { budget_bytes: 67108864, estimate: None }))";
    let cases: [(&str, u32, u32, &str); 5] = [
        ("{}", 20, 3, "Ok(20 traces, 60 spans)"),
        ("{}", 1000, 28, "Ok(1000 traces, 28000 spans)"),
        ("{}", 70000, 28, ceiling),
        ("{}", u32::MAX, u32::MAX, ceiling),
        (
            "{ status = error }",
            u32::MAX,
            u32::MAX,
            "Ok(70000 traces, 70000 spans)",
        ),
    ];
    let mut wrong = Vec::new();
    for (query, limit, spss, want) in cases {
        let plan = plan_of(&engine, &parse_query(query), window, limit, spss);
        let started = std::time::Instant::now();
        let got = shape(&engine.search_routed(&plan).await);
        eprintln!("{query} ({limit}, {spss}): {got}, {:?}", started.elapsed());
        if !covered(&plan) {
            wrong.push(format!("{query} ({limit}, {spss}): not covered"));
        }
        if got != want {
            wrong.push(format!(
                "{query} ({limit}, {spss})\n  want: {want}\n  got:  {got}"
            ));
        }
    }
    drop_db(&db).await;
    assert!(wrong.is_empty(), "{}", wrong.join("\n\n"));
}

/// Section 6.9: a run-time demand the statement raises sends the request
/// to today's engine, whose own answer stands — and the query log shows
/// the statement was tried first.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn search_routed_answers_a_run_time_demand_on_todays_engine() {
    skip_unless_live!();
    const MS: i64 = 1_000_000;
    let base_ns = (now_ns() / 1_000_000_000) * 1_000_000_000;
    let window = (base_ns, base_ns + CATALOGUE_WINDOW_NS);
    let spans: Vec<Span> = [str_value("hello"), bool_value(true), bool_value(false)]
        .into_iter()
        .enumerate()
        .map(|(i, a)| {
            let i = i as u8;
            span_of(
                vec![0x44; 16],
                vec![0, 0, 0, 0, 0, 0, 0, i + 1],
                if i == 0 {
                    Vec::new()
                } else {
                    vec![0, 0, 0, 0, 0, 0, 0, 1]
                },
                "demand",
                1,
                base_ns + i64::from(i) * MS,
                MS,
                vec![kv("a", a), kv("b", int_value(1))],
                0,
                Vec::new(),
                Vec::new(),
            )
        })
        .collect();
    let body = ExportTraceServiceRequest {
        resource_spans: vec![ResourceSpans {
            resource: Some(Resource {
                attributes: vec![kv("service.name", str_value("svc-d"))],
                dropped_attributes_count: 0,
                entity_refs: Vec::new(),
            }),
            scope_spans: vec![ScopeSpans {
                scope: Some(scope()),
                spans,
                schema_url: String::new(),
            }],
            schema_url: String::new(),
        }],
    };
    let (db, client) = seed_both(
        pulsus_testkit::test_db("pulsus_read_it_t591p3_demand"),
        &[body],
        3,
        "t591p3-demand",
    )
    .await;
    let engine = engine_of(&db).await;
    let demand = "expression (!.a) expected a boolean";
    let cases = [
        (r#"{ !.a = .b }"#, true, Err(demand)),
        (r#"{ !.a = 1 }"#, false, Err(demand)),
        (r#"{ .a }"#, true, Ok(1usize)),
    ];
    let mut wrong = Vec::new();
    // The fork's answers first, and the query log read before today's
    // engine runs at all: a read of today's tables after the statement's
    // 395 can then only be the fork's own retry.
    let t0 = now_ns();
    let mut routed = Vec::new();
    for (query, want_covered, _) in &cases {
        let plan = plan_of(&engine, &parse_query(query), window, 20, 3);
        if covered(&plan) != *want_covered {
            wrong.push(format!(
                "{query}: covered {}, want {want_covered}",
                covered(&plan)
            ));
        }
        routed.push(engine.search_routed(&plan).await);
    }
    client
        .execute(
            "SYSTEM FLUSH LOGS",
            &QuerySettings::new(),
            Idempotency::Idempotent,
        )
        .await
        .expect("flush the logs");
    #[derive(Row, serde::Serialize, serde::Deserialize, Debug)]
    struct Logged {
        at: i64,
        code: i32,
        statement: u8,
        today: u8,
    }
    let sql = format!(
        "SELECT toUnixTimestamp64Micro(event_time_microseconds) AS at, exception_code AS code, \
         toUInt8(startsWith(query, 'WITH (SELECT (groupArray(trace_id)')) AS statement, \
         toUInt8(has(tables, '{db}.trace_recent') OR has(tables, '{db}.trace_spans')) AS today \
         FROM system.query_log WHERE has(databases, '{db}') \
         AND type IN ('ExceptionBeforeStart', 'ExceptionWhileProcessing', 'QueryFinish') \
         AND event_time_microseconds >= toDateTime64({}, 6) ORDER BY at",
        t0 as f64 / 1e9
    );
    let mut logged = Vec::new();
    let mut stream = client
        .query_stream::<Logged>(&sql, &QuerySettings::new())
        .await
        .expect("read the query log");
    while let Some(row) = stream.next().await {
        logged.push(row.expect("decode a query log row"));
    }
    // Then today's engine, whose answer the fork's must equal exactly —
    // the same error, of the same kind, not merely the same message.
    for ((query, _, want), routed) in cases.iter().zip(&routed) {
        let plan = plan_of(&engine, &parse_query(query), window, 20, 3);
        let today = engine.search(&plan).await;
        for (side, out) in [("routed", routed), ("today", &today)] {
            let ok = match (want, out) {
                (Err(m), Err(e)) => e.to_string().contains(m),
                (Ok(n), Ok(o)) => o.traces.len() == *n,
                _ => false,
            };
            if !ok {
                wrong.push(format!("{query} {side}: want {want:?}, got {}", shape(out)));
            }
        }
        let (r, t) = (
            format!("{:?}", routed.as_ref().err()),
            format!("{:?}", today.as_ref().err()),
        );
        if r != t {
            wrong.push(format!(
                "{query}: the fork's error\n  {r}\nis not today's\n  {t}"
            ));
        }
    }
    drop_db(&db).await;
    let tried = logged
        .iter()
        .find(|r| r.code == 395 && r.statement == 1)
        .map(|r| r.at);
    match tried {
        None => wrong.push(format!(
            "no 395 row for the statement in the query log: {logged:?}"
        )),
        Some(at) => {
            if !logged.iter().any(|r| r.today == 1 && r.at > at) {
                wrong.push(format!(
                    "no read of today's tables after the statement's 395: {logged:?}"
                ));
            }
        }
    }
    assert!(wrong.is_empty(), "{}", wrong.join("\n"));
}

/// Section 6.10: the decode is charged. 70,000 one-span traces, each span
/// holding one attribute with a 4,000-byte key: the rows are small, and
/// the response copies the key into every span it returns.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn search_routed_charges_the_response_it_builds() {
    skip_unless_live!();
    let (db, _client, w) =
        seed_long_keys(pulsus_testkit::test_db("pulsus_read_it_t591p3_charged")).await;
    let engine = engine_of(&db).await;
    let window = (w.first_included_ns(), w.last_included_ns() + 1);
    let query = format!(r#"{{ span.{} = "v" }}"#, "k".repeat(4000));
    let mut wrong = Vec::new();
    for (limit, spss, want) in [
        (20, 3, "Ok(20 traces, 20 spans)".to_string()),
        (
            u32::MAX,
            u32::MAX,
            "Err(QueryTooBroad(ScanBudgetBytes { budget_bytes: 268435456, estimate: None }))"
                .to_string(),
        ),
    ] {
        let plan = plan_of(&engine, &parse_query(&query), window, limit, spss);
        let started = std::time::Instant::now();
        let got = shape(&engine.search_routed(&plan).await);
        eprintln!("({limit}, {spss}): {got}, {:?}", started.elapsed());
        if !covered(&plan) {
            wrong.push(format!("({limit}, {spss}): not covered"));
        }
        if got != want {
            wrong.push(format!("({limit}, {spss})\n  want: {want}\n  got:  {got}"));
        }
    }
    drop_db(&db).await;
    assert!(wrong.is_empty(), "{}", wrong.join("\n\n"));
}

/// Section 6.10's database: 70,000 one-span traces over three hours, each
/// span holding `{ <4000 × k>: "v" }`, then the per-trace table, as corpus
/// S builds it.
async fn seed_long_keys(db: String) -> (String, ChClient, WindowSql) {
    let client = fresh_db(&db).await;
    let base_ns = (now_ns() / 1_000_000_000) * 1_000_000_000 - CORPUS_S_NS;
    run_bounded(
        &client,
        format!(
            "INSERT INTO {SPANS_TABLE} (trace_id, span_id, parent_span_id, start_ns, duration_ns, \
             service, name, kind, end_ns, service_type, attrs) \
             SELECT sipHash128(t), reinterpretAsFixedString(cityHash64(t, 0)), \
             toFixedString('', 8), {base_ns} + t * 1000000, 1000000, 'frontend', 'op', 1, \
             toUInt64({base_ns} + t * 1000000 + 1000000), 'string', \
             CAST(concat('{{\"', repeat('k', 4000), '\":\"v\"}}') AS JSON) \
             FROM (SELECT number AS t FROM numbers(70000))"
        ),
    )
    .await;
    run_bounded(&client, TRACES_FROM_SPANS.to_string()).await;
    let seeded = count(&client, &format!("SELECT count() AS n FROM {SPANS_TABLE}")).await;
    assert_eq!(seeded, 70_000, "70,000 spans");
    let w = WindowSql::start_closed_end_open(base_ns, base_ns + CORPUS_S_NS);
    (db, client, w)
}

// =====================================================================
// Issue #592 part 2 — by() and coalesce() on the search statement
// =====================================================================

/// The window [`by_fixtures`] land in: 200 s from `base_ns`.
const BY_WINDOW_NS: i64 = 200_000_000_000;

/// An answer with its groups: per trace `(trace, matched, span ids)` as
/// [`answer_of`] writes it, then, when the trace carries groups,
/// `{value matched [span ids]; …}` in the response's order. A value is
/// its text, `int:` or `double:` and its number, `bool:` and its value,
/// or `nil`.
fn grouped_answer_of(
    out: &Result<pulsus_read::traces::SearchOutput, pulsus_read::logql::ReadError>,
) -> String {
    match out {
        Err(e) => format!("Err({e})"),
        Ok(o) => o
            .traces
            .iter()
            .map(grouped_trace_of)
            .collect::<Vec<_>>()
            .join("; "),
    }
}

/// One trace of [`grouped_answer_of`].
fn grouped_trace_of(t: &pulsus_read::traces::TraceSearchResult) -> String {
    use pulsus_read::traces::GroupValue;
    let ids = |spans: &[pulsus_read::traces::SpanSummary]| -> String {
        spans
            .iter()
            .map(|s| format!("{:02x}", s.span_id[7]))
            .collect::<Vec<_>>()
            .join(", ")
    };
    let mut text = format!("{:02x} {} [{}]", t.trace_id[15], t.matched, ids(&t.spans));
    if let Some(groups) = &t.groups {
        let groups: Vec<String> = groups
            .iter()
            .map(|g| {
                let value = match g.attributes.first().map(|(_, v)| v) {
                    Some(GroupValue::Str(s)) => s.clone(),
                    Some(GroupValue::Int(i)) => format!("int:{i}"),
                    Some(GroupValue::Double(bits)) => format!("double:{}", f64::from_bits(*bits)),
                    Some(GroupValue::Bool(b)) => format!("bool:{b}"),
                    Some(GroupValue::Nil) => "nil".to_string(),
                    None => "<no key>".to_string(),
                };
                format!("{value} {} [{}]", g.matched, ids(&g.spans))
            })
            .collect();
        text.push_str(&format!(" {{{}}}", groups.join("; ")));
    }
    text
}

/// One server span of 0.1 s at `at_s` seconds after `base_ns`.
fn by_span(base_ns: i64, trace: u8, span: u8, name: &str, at_s: i64, attrs: Vec<KeyValue>) -> Span {
    const S: i64 = 1_000_000_000;
    span_of(
        vec![trace; 16],
        vec![0, 0, 0, 0, 0, 0, 0, span],
        Vec::new(),
        name,
        2,
        base_ns + at_s * S,
        S / 10,
        attrs,
        0,
        Vec::new(),
        Vec::new(),
    )
}

/// One push of `spans` in a resource named `service`.
fn by_body(service: &str, spans: Vec<Span>) -> ExportTraceServiceRequest {
    ExportTraceServiceRequest {
        resource_spans: vec![ResourceSpans {
            resource: Some(Resource {
                attributes: vec![kv("service.name", str_value(service))],
                dropped_attributes_count: 0,
                entity_refs: Vec::new(),
            }),
            scope_spans: vec![ScopeSpans {
                scope: Some(scope()),
                spans,
                schema_url: String::new(),
            }],
            schema_url: String::new(),
        }],
    }
}

/// Issue #592 part 2's fixtures (section 7.2), by label: their bodies and
/// span counts. Spans are kind server and 0.1 s long; ids are written in
/// hex, as [`grouped_answer_of`] writes them.
///
/// - `rpc`: resource `checkout` holds trace `e1`'s spans 41-46 and `e2`'s
///   48; resource `cart` holds `e1`'s 47. `rpc.method` is `"Get"`,
///   `"List"`, none, `"Get"`, the integer 1, the double 1.0 (41-46), 48
///   `"List"`, 47 `"Get"`.
/// - `firstseen`: `f1`'s 51 (`k = "x"`, `c`), 52 (`"y"`, `b`), 53 (`"x"`, `b`).
/// - `values`: trace `90`'s spans 91-97 (name `all`) hold key `v` as an
///   array of strings, a key-value list, bytes, an array of integers, a
///   string, nothing and an empty array; trace `91`'s a1-a5 (`arr`) key
///   `arrx` as the two arrays, the empty array, a string and nothing;
///   `92`'s b1-b2 (`kv`) key `kvx` as a key-value list and a string; `93`'s
///   c1-c2 (`bytes`) key `bytesx` as bytes and a string.
/// - `topk`: trace `60`'s spans 60-65 hold `k = "g0"` … `"g5"` at 100-105
///   s; traces `70` … `84` hold one span each, `k = "x"`, at 50-70 s.
fn by_fixtures(base_ns: i64) -> Vec<(&'static str, Vec<ExportTraceServiceRequest>, u64)> {
    let sp = |trace, span, name, at, attrs| by_span(base_ns, trace, span, name, at, attrs);
    let method = |v: AnyValue| vec![kv("rpc.method", v)];
    let k = |v: &str| vec![kv("k", str_value(v))];
    let kvlist = || kvlist_value(vec![kv("a", int_value(1)), kv("b", str_value("z"))]);
    let rpc = vec![
        by_body(
            "checkout",
            vec![
                sp(0xe1, 0x41, "op", 1, method(str_value("Get"))),
                sp(0xe1, 0x42, "op", 2, method(str_value("List"))),
                sp(0xe1, 0x43, "op", 3, Vec::new()),
                sp(0xe1, 0x44, "op", 4, method(str_value("Get"))),
                sp(0xe1, 0x45, "op", 5, method(int_value(1))),
                sp(0xe1, 0x46, "op", 6, method(double_value(1.0))),
                sp(0xe2, 0x48, "op", 8, method(str_value("List"))),
            ],
        ),
        by_body(
            "cart",
            vec![sp(0xe1, 0x47, "op", 7, method(str_value("Get")))],
        ),
    ];
    let firstseen = vec![by_body(
        "svc",
        vec![
            sp(0xf1, 0x51, "c", 1, k("x")),
            sp(0xf1, 0x52, "b", 2, k("y")),
            sp(0xf1, 0x53, "b", 3, k("x")),
        ],
    )];
    let v = |key: &str, value: AnyValue| vec![kv(key, value)];
    let values = vec![by_body(
        "svc",
        vec![
            sp(0x90, 0x91, "all", 1, v("v", str_array_value(&["x", "y"]))),
            sp(0x90, 0x92, "all", 2, v("v", kvlist())),
            sp(0x90, 0x93, "all", 3, v("v", bytes_value(&[1, 2, 3]))),
            sp(0x90, 0x94, "all", 4, v("v", int_array_value(&[1, 2]))),
            sp(0x90, 0x95, "all", 5, v("v", str_value("x"))),
            sp(0x90, 0x96, "all", 6, Vec::new()),
            sp(0x90, 0x97, "all", 7, v("v", str_array_value(&[]))),
            sp(
                0x91,
                0xa1,
                "arr",
                1,
                v("arrx", str_array_value(&["x", "y"])),
            ),
            sp(0x91, 0xa2, "arr", 2, v("arrx", int_array_value(&[1, 2]))),
            sp(0x91, 0xa3, "arr", 3, v("arrx", str_array_value(&[]))),
            sp(0x91, 0xa4, "arr", 4, v("arrx", str_value("x"))),
            sp(0x91, 0xa5, "arr", 5, Vec::new()),
            sp(0x92, 0xb1, "kv", 1, v("kvx", kvlist())),
            sp(0x92, 0xb2, "kv", 2, v("kvx", str_value("x"))),
            sp(0x93, 0xc1, "bytes", 1, v("bytesx", bytes_value(&[1, 2, 3]))),
            sp(0x93, 0xc2, "bytes", 2, v("bytesx", str_value("x"))),
        ],
    )];
    let mut topk_spans: Vec<Span> = (0..6u8)
        .map(|i| {
            sp(
                0x60,
                0x60 + i,
                "op",
                100 + i64::from(i),
                k(&format!("g{i}")),
            )
        })
        .collect();
    for i in 0..21u8 {
        topk_spans.push(sp(0x70 + i, 0x70 + i, "op", 50 + i64::from(i), k("x")));
    }
    vec![
        ("rpc", rpc, 8),
        ("firstseen", firstseen, 3),
        ("values", values, 16),
        ("topk", vec![by_body("svc", topk_spans)], 27),
    ]
}

/// Seeds the [`by_fixtures`] fixture `label` in both stores of the
/// database `test`'s own name gives: two tests may seed one fixture, and
/// the suite runs them at once.
async fn seed_by_fixture(label: &str, test: &str, base_ns: i64) -> (String, ChClient) {
    let (_, bodies, spans) = by_fixtures(base_ns)
        .into_iter()
        .find(|(l, ..)| *l == label)
        .unwrap_or_else(|| panic!("no fixture {label}"));
    seed_both(
        pulsus_testkit::test_db(&format!("pulsus_read_it_t592p2_{test}")),
        &bodies,
        spans,
        &format!("t592p2-{label}"),
    )
    .await
}

/// One routed search, then the query log's statement count for it, then
/// today's answer: `(today, routed, statements)`. The query log is read
/// before today's engine runs, so the count is the fork's alone. Both
/// answers are normalised as [`normalise_today`] does: a request the
/// statement hands over is answered by today's engine, roots and all.
async fn routed_and_today(
    engine: &pulsus_read::TraceEngine,
    client: &ChClient,
    db: &str,
    plan: &pulsus_read::SearchPlan,
) -> (
    Result<pulsus_read::traces::SearchOutput, pulsus_read::logql::ReadError>,
    Result<pulsus_read::traces::SearchOutput, pulsus_read::logql::ReadError>,
    u64,
) {
    let t0 = now_ns();
    let routed = engine.search_routed(plan).await.map(normalise_today);
    let (statements, _) = settled_statements(client, db, t0).await;
    let today = engine.search(plan).await.map(normalise_today);
    (today, routed, statements)
}

/// Records a case whose routed answer is not today's, or not its literal.
fn check_grouped(
    wrong: &mut Vec<String>,
    label: &str,
    today: &Result<pulsus_read::traces::SearchOutput, pulsus_read::logql::ReadError>,
    routed: &Result<pulsus_read::traces::SearchOutput, pulsus_read::logql::ReadError>,
    literal: &str,
) {
    if format!("{today:?}") != format!("{routed:?}") {
        wrong.push(format!(
            "{label}\n  today:  {}\n  routed: {}",
            grouped_answer_of(today),
            grouped_answer_of(routed)
        ));
        return;
    }
    if grouped_answer_of(routed) != literal {
        wrong.push(format!(
            "{label}\n  literal: {literal}\n  both:    {}",
            grouped_answer_of(routed)
        ));
    }
}

/// `T-A8`: one spanset per value and stored type, a span without the key
/// in the `nil` group, in the order the groups' first spans appear; one
/// statement.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn t_a8_one_spanset_per_value_and_stored_type() {
    skip_unless_live!();
    let base_ns = (now_ns() / 1_000_000_000) * 1_000_000_000;
    let (db, client) = seed_by_fixture("rpc", "ta8", base_ns).await;
    let engine = engine_of(&db).await;
    let query = r#"{ resource.service.name = "checkout" } | by(span.rpc.method)"#;
    let plan = plan_of(
        &engine,
        &parse_query(query),
        (base_ns, base_ns + BY_WINDOW_NS),
        20,
        3,
    );
    let (today, routed, statements) = routed_and_today(&engine, &client, &db, &plan).await;
    drop_db(&db).await;
    let mut wrong = Vec::new();
    if !covered(&plan) {
        wrong.push(format!(
            "{query}: today's engine's, must be the statement's"
        ));
    }
    check_grouped(
        &mut wrong,
        query,
        &today,
        &routed,
        "e2 1 [48] {List 1 [48]}; \
         e1 6 [41, 42, 43] {Get 2 [41, 44]; List 1 [42]; nil 1 [43]; int:1 1 [45]; double:1 1 [46]}",
    );
    if statements != 1 {
        wrong.push(format!("{query}: {statements} statements, want 1"));
    }
    assert!(wrong.is_empty(), "{}", wrong.join("\n"));
}

/// The integer 1 and the double 1 are two groups: fixture C's trace
/// `11…11` under `{ } | by(span.a)`.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_integer_and_the_double_do_not_merge() {
    skip_unless_live!();
    let base_ns = (now_ns() / 1_000_000_000) * 1_000_000_000;
    let window = (base_ns, base_ns + CATALOGUE_WINDOW_NS);
    let (db, _client) = seed_both(
        pulsus_testkit::test_db("pulsus_read_it_t592p2_intdouble"),
        &fixture_catalogue_bodies(base_ns),
        34,
        "t592p2-intdouble",
    )
    .await;
    let engine = engine_of(&db).await;
    let query = "{ } | by(span.a)";
    let plan = plan_of(&engine, &parse_query(query), window, 20, 3);
    let today = engine.search(&plan).await.map(normalise_today);
    let routed = engine.search_routed(&plan).await;
    drop_db(&db).await;
    let mut wrong = Vec::new();
    if !covered(&plan) {
        wrong.push(format!(
            "{query}: today's engine's, must be the statement's"
        ));
    }
    if format!("{today:?}") != format!("{routed:?}") {
        wrong.push(format!(
            "{query}\n  today:  {}\n  routed: {}",
            grouped_answer_of(&today),
            grouped_answer_of(&routed)
        ));
    }
    let trace = routed
        .as_ref()
        .ok()
        .and_then(|o| o.traces.iter().find(|t| t.trace_id == [0x11; 16]))
        .map(grouped_trace_of);
    let want = "11 3 [01, 02, 03] {int:1 1 [01]; nil 1 [02]; double:1 1 [03]}";
    if trace.as_deref() != Some(want) {
        wrong.push(format!(
            "trace 11…11\n  want: {want}\n  got:  {trace:?}\n  answer: {}",
            grouped_answer_of(&routed)
        ));
    }
    assert!(wrong.is_empty(), "{}", wrong.join("\n"));
}

/// `coalesce()` merges the groups back: no groups, the union's spans,
/// and the same answer as the ungrouped query.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn coalesce_drops_the_key() {
    skip_unless_live!();
    let base_ns = (now_ns() / 1_000_000_000) * 1_000_000_000;
    let window = (base_ns, base_ns + BY_WINDOW_NS);
    let (db, client) = seed_by_fixture("rpc", "coalesce", base_ns).await;
    let engine = engine_of(&db).await;
    let query = r#"{ resource.service.name = "checkout" } | by(span.rpc.method) | coalesce()"#;
    let plan = plan_of(&engine, &parse_query(query), window, 20, 3);
    let (today, routed, statements) = routed_and_today(&engine, &client, &db, &plan).await;
    let flat = engine
        .search_routed(&plan_of(
            &engine,
            &parse_query(r#"{ resource.service.name = "checkout" }"#),
            window,
            20,
            3,
        ))
        .await;
    drop_db(&db).await;
    let mut wrong = Vec::new();
    if !covered(&plan) {
        wrong.push(format!(
            "{query}: today's engine's, must be the statement's"
        ));
    }
    check_grouped(
        &mut wrong,
        query,
        &today,
        &routed,
        "e2 1 [48]; e1 6 [41, 42, 43]",
    );
    if format!("{flat:?}") != format!("{routed:?}") {
        wrong.push(format!(
            "{query} is not the ungrouped answer\n  ungrouped: {}\n  coalesced: {}",
            grouped_answer_of(&flat),
            grouped_answer_of(&routed)
        ));
    }
    if statements != 1 {
        wrong.push(format!("{query}: {statements} statements, want 1"));
    }
    assert!(wrong.is_empty(), "{}", wrong.join("\n"));
}

/// The top-K keeps traces, not groups: trace `60`'s six groups take one
